fn loop_guard_tool_error(call_id: &str, tool_name: &str, message: &str) -> tau_proto::ToolError {
    tau_proto::ToolError {
        presentation: Default::default(),
        call_id: call_id.into(),
        tool_name: ToolName::new(tool_name),
        tool_type: tau_proto::ToolType::Function,
        message: message.to_owned(),
        details: None,
        originator: tau_proto::PromptOriginator::User,
        display: None,
    }
}

#[test]
fn loop_guard_detects_repeated_assistant_text_once_then_blocks() {
    let td = TempDir::new().expect("tempdir");
    let sp = td.path().join("state");
    let mut h = echo_harness(&sp).expect("start");
    let cid = ensure_test_user_agent(&mut h);
    let text =
        "I will keep trying the same plan without taking any tool action or making progress.";

    h.record_assistant_loop_signature(&cid, Some(text));
    h.record_assistant_loop_signature(&cid, Some(text));
    h.record_assistant_loop_signature(&cid, Some(text));

    let conv = h.agents.get(&cid).expect("agent");
    assert_eq!(conv.pending_prompts.len(), 1);
    assert!(conv.pending_prompts[0].text.contains("Loop guard:"));
    assert!(!conv.loop_guard.stop_automatic_continuation());

    h.mark_loop_guard_breakers_dispatched(&cid);
    h.record_assistant_loop_signature(&cid, Some(text));

    let conv = h.agents.get(&cid).expect("agent");
    assert_eq!(conv.pending_prompts.len(), 1);
    assert!(conv.loop_guard.stop_automatic_continuation());
    assert!(event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::HarnessNotice(notice)
            if notice.message.contains("Loop guard stopped automatic continuation")
    )));
}

#[test]
fn loop_guard_repeated_assistant_text_flows_through_provider_responses() {
    let td = TempDir::new().expect("tempdir");
    let sp = td.path().join("state");
    let mut h = echo_harness(&sp).expect("start");
    h.selected_model = Some("test/model".into());
    let cid = ensure_test_user_agent(&mut h);
    let text =
        "I will keep trying the same plan without taking any tool action or making progress.";

    for idx in 0..3 {
        let spid: AgentPromptId = test_agent_prompt_id(format!("sp-loop-text-{idx}"));
        seed_agent_thinking(&mut h, &cid, spid.as_str());
        h.prompt_agents.insert(spid.clone(), cid.clone());
        h.handle_provider_response_finished(provider_text_response(
            &spid,
            tau_proto::AgentId::parse("main").expect("agent id"),
            text,
        ))
        .expect("response handled");
    }

    assert!(event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::AgentPromptSteered(steered)
            if steered.message_class == tau_proto::PromptMessageClass::Internal
                && steered.text.contains("Loop guard:")
    )));
    assert!(
        h.agents
            .get(&cid)
            .expect("agent")
            .pending_prompts
            .is_empty()
    );

    let spid = h
        .agents
        .get(&cid)
        .and_then(|conv| conv.in_flight_prompt.clone())
        .expect("loop breaker prompt dispatched");
    h.handle_provider_response_finished(provider_text_response(
        &spid,
        tau_proto::AgentId::parse("main").expect("agent id"),
        text,
    ))
    .expect("response handled");

    assert!(
        h.agents
            .get(&cid)
            .expect("agent")
            .loop_guard
            .stop_automatic_continuation()
    );
    assert!(event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::HarnessNotice(notice)
            if notice.message.contains("Loop guard stopped automatic continuation")
    )));
}

#[test]
fn loop_guard_provider_repetition_response_queues_pivot_then_blocks() {
    // Provider-side stream repetition is trusted only as a loop-guard trigger:
    // the provider's error is display text, while the harness uses a fixed pivot
    // reason and blocks only after the breaker was tried.
    let td = TempDir::new().expect("tempdir");
    let sp = td.path().join("state");
    let mut h = echo_harness(&sp).expect("start");
    h.selected_model = Some("test/model".into());
    let cid = ensure_test_user_agent(&mut h);

    let spid: AgentPromptId = test_agent_prompt_id("sp-provider-repetition-1");
    seed_agent_thinking(&mut h, &cid, spid.as_str());
    h.prompt_agents.insert(spid.clone(), cid.clone());
    h.handle_provider_response_finished(provider_repetition_response(
        &spid,
        tau_proto::AgentId::parse("main").expect("agent id"),
    ))
    .expect("response handled");

    assert!(event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::AgentPromptSteered(steered)
            if steered.message_class == tau_proto::PromptMessageClass::Internal
                && steered.text.contains("provider detected a tight exact stream repetition")
    )));
    let spid = h
        .agents
        .get(&cid)
        .and_then(|conv| conv.in_flight_prompt.clone())
        .expect("loop breaker prompt dispatched");
    h.handle_provider_response_finished(provider_repetition_response(
        &spid,
        tau_proto::AgentId::parse("main").expect("agent id"),
    ))
    .expect("response handled");

    assert!(
        h.agents
            .get(&cid)
            .expect("agent")
            .loop_guard
            .stop_automatic_continuation()
    );
    assert!(event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::HarnessNotice(notice)
            if notice.level == tau_proto::NoticeLevel::Warning
                && notice.always_show
                && notice.message.contains("Loop guard stopped automatic continuation")
    )));
}

#[test]
fn repetition_response_with_output_items_is_cleared_before_persisting() {
    // The harness enforces the repetition-detected empty-output invariant at the
    // provider boundary so a buggy provider cannot smuggle text or tool calls in
    // a loop-guard terminal response.
    let td = TempDir::new().expect("tempdir");
    let sp = td.path().join("state");
    let mut h = echo_harness(&sp).expect("start");
    h.selected_model = Some("test/model".into());
    let cid = ensure_test_user_agent(&mut h);
    let spid: AgentPromptId = test_agent_prompt_id("sp-provider-repetition-malformed");
    seed_agent_thinking(&mut h, &cid, spid.as_str());
    h.prompt_agents.insert(spid.clone(), cid.clone());
    let mut response =
        provider_repetition_response(&spid, tau_proto::AgentId::parse("main").expect("agent id"));
    response.output_items = provider_text_response(
        &spid,
        tau_proto::AgentId::parse("main").expect("agent id"),
        "this text must be discarded",
    )
    .output_items;

    h.handle_provider_response_finished(response)
        .expect("response handled");

    assert!(!event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::ProviderResponseFinished(finished)
            if finished
                .output_items
                .iter()
                .any(|item| matches!(item, ContextItem::Message(_)))
    )));
}

#[test]
fn side_agent_repetition_response_propagates_error_result() {
    // Empty repetition/error provider responses from extension-originated side
    // agents must not look like successful empty delegation results.
    let td = TempDir::new().expect("tempdir");
    let sp = td.path().join("state");
    let mut h = echo_harness(&sp).expect("start");
    h.selected_model = Some("test/model".into());
    let frames = connect_test_client(&mut h, "conn-side", tau_proto::ClientKind::External);

    h.handle_start_agent_request(
        &crate::test_connection_id("conn-side"),
        StartAgentRequest {
            trusted_internal_spans: Vec::new(),
            parent_agent: None,
            query_id: "q-repetition".to_owned(),
            instruction: "Summarize in one sentence.".to_owned(),
            role: None,
            input_stats: tau_proto::ToolUseStats::default(),
            tool_call_id: None,
            task_name: None,
        },
    )
    .expect("start-agent request");
    let (side_spid, side_cid) = h
        .prompt_agents
        .iter()
        .find_map(|(spid, prompt_cid)| {
            (prompt_cid.as_str() != "default").then(|| (spid.clone(), prompt_cid.clone()))
        })
        .expect("side prompt id");
    let side_agent_id = durable_agent_id_for_conversation(&h, &side_cid);
    let mut response = provider_repetition_response(
        &side_spid,
        tau_proto::AgentId::parse("side").expect("agent id"),
    );
    response.originator = tau_proto::PromptOriginator::Extension {
        name: crate::test_extension_name("conn-side"),
        query_id: "q-repetition".to_owned(),
    };
    response.error = Some("provider stream repetition detected".to_owned());

    h.handle_provider_response_finished(response)
        .expect("side response handled");

    assert!(!h.agents.contains_key(&side_cid));
    assert!(!h.session_loaded_agents.contains(&side_agent_id));
    assert!(
        h.store
            .session_events("s1")
            .expect("session events")
            .iter()
            .any(|record| matches!(
                &record.event,
                Event::SessionAgentUnloaded(unloaded) if unloaded.agent_id == side_agent_id
            ))
    );
    let result = frames
        .lock()
        .expect("frames")
        .iter()
        .find_map(|routed| match peel_inner_event(&routed.frame) {
            Some(Event::StartAgentResult(result)) if result.query_id == "q-repetition" => {
                Some(result.clone())
            }
            _ => None,
        })
        .expect("start-agent result routed");
    assert!(result.text.is_empty());
    assert_eq!(result.error.as_deref(), Some("provider failure: unknown"));
}

#[test]
fn side_agent_error_response_propagates_error_result() {
    // Plain provider errors with no assistant text should also reach the
    // StartAgentResult error field instead of becoming silent empty text.
    let td = TempDir::new().expect("tempdir");
    let sp = td.path().join("state");
    let mut h = echo_harness(&sp).expect("start");
    h.selected_model = Some("test/model".into());
    let frames = connect_test_client(&mut h, "conn-side-error", tau_proto::ClientKind::External);

    h.handle_start_agent_request(
        &crate::test_connection_id("conn-side-error"),
        StartAgentRequest {
            trusted_internal_spans: Vec::new(),
            parent_agent: None,
            query_id: "q-error".to_owned(),
            instruction: "Summarize in one sentence.".to_owned(),
            role: None,
            input_stats: tau_proto::ToolUseStats::default(),
            tool_call_id: None,
            task_name: None,
        },
    )
    .expect("start-agent request");
    let side_spid = h
        .prompt_agents
        .iter()
        .find_map(|(spid, prompt_cid)| (prompt_cid.as_str() != "default").then_some(spid.clone()))
        .expect("side prompt id");
    h.handle_provider_response_finished(ProviderResponseFinished {
        estimated_api_cost_rates: None,
        estimated_api_cost_increment: None,

        agent_prompt_id: side_spid.clone(),
        agent_id: tau_proto::AgentId::parse("side").expect("agent id"),
        output_items: Vec::new(),
        stop_reason: tau_proto::ProviderStopReason::Error,
        error: Some("provider failed".to_owned()),
        failure_kind: Some(tau_proto::ProviderFailureKind::ContextWindowExceeded),
        context_limit_telemetry: None,
        recovery_disposition: tau_proto::ContextRecoveryDisposition::None,
        usage: None,
        originator: tau_proto::PromptOriginator::Extension {
            name: crate::test_extension_name("conn-side-error"),
            query_id: "q-error".to_owned(),
        },
        compaction_original_input_tokens: None,
        compaction_compacted_input_tokens: None,
        backend: None,
        provider_response_id: None,
        ws_pool_delta: None,
    })
    .expect("side response handled");

    let result = frames
        .lock()
        .expect("frames")
        .iter()
        .find_map(|routed| match peel_inner_event(&routed.frame) {
            Some(Event::StartAgentResult(result)) if result.query_id == "q-error" => {
                Some(result.clone())
            }
            _ => None,
        })
        .expect("start-agent result routed");
    assert!(result.text.is_empty());
    assert_eq!(
        result.error.as_deref(),
        Some("provider failure: context_window_exceeded")
    );
    assert!(
        !format!("{result:?}").contains("provider failed"),
        "raw provider diagnostics must not cross the delegated result boundary"
    );
    assert!(!h.prompt_agents.contains_key(&side_spid));
    assert!(h.turn_state.is_idle());
}

/// A rejected tool call can synchronously dispatch the side agent's automatic
/// continuation. The rejection path must preserve that new running state so
/// request completion cannot unload the agent before the continuation finishes.
#[test]
fn rejected_side_agent_tool_call_preserves_dispatched_continuation() {
    let td = TempDir::new().expect("tempdir");
    let sp = td.path().join("state");
    let mut h = echo_harness(&sp).expect("start");
    h.selected_model = Some("test/model".into());
    let _frames = connect_test_client(&mut h, "conn-side-invalid", tau_proto::ClientKind::External);
    h.submit_user_prompt(test_session_id("s1"), "parent prompt".to_owned())
        .expect("submit parent");
    let parent = h
        .agents
        .get(&test_user_agent(&h))
        .and_then(|agent| agent.agent_id.as_deref())
        .and_then(|agent_id| tau_proto::AgentId::parse(agent_id).ok())
        .expect("parent agent id");

    h.handle_start_agent_request(
        &crate::test_connection_id("conn-side-invalid"),
        StartAgentRequest {
            trusted_internal_spans: Vec::new(),
            parent_agent: Some(parent),
            query_id: "q-invalid-tool".to_owned(),
            instruction: "review the change".to_owned(),
            role: None,
            input_stats: tau_proto::ToolUseStats::default(),
            tool_call_id: None,
            task_name: None,
        },
    )
    .expect("start side agent");
    let side_cid = ext_query_cid(&h, "q-invalid-tool").expect("side conversation");
    let _interceptor = connect_test_tool(&mut h, "side-invalid-terminal-interceptor");
    h.handle_extension_event(
        "side-invalid-terminal-interceptor",
        TestProtocolItem::Message(TestMessage::Intercept(Intercept {
            selectors: vec![EventSelector::Exact(
                tau_proto::EventName::PROVIDER_TOOL_ERROR,
            )],
            priority: InterceptionPriority::new(0),
        })),
    )
    .expect("register side terminal interceptor");
    let first_prompt_id = h
        .agents
        .get(&side_cid)
        .and_then(|agent| agent.in_flight_prompt.clone())
        .expect("first side prompt");
    let mut response = provider_text_response(
        &first_prompt_id,
        durable_agent_id_for_conversation(&h, &side_cid),
        "",
    );
    response.output_items = vec![ContextItem::ToolCall(ToolCallItem {
        call_id: "invalid-side-call".into(),
        name: ToolName::new("tool_that_does_not_exist"),
        tool_type: tau_proto::ToolType::Function,
        arguments: CborValue::Map(Vec::new()),
        raw_arguments_json: None,
        responses_envelope: None,
    })];
    response.stop_reason = tau_proto::ProviderStopReason::ToolCalls;
    response.originator = tau_proto::PromptOriginator::Extension {
        name: crate::test_extension_name("conn-side-invalid"),
        query_id: "q-invalid-tool".to_owned(),
    };

    h.handle_provider_response_finished(response)
        .expect("reject invalid side-agent tool call");

    assert!(h.pending_intercept.is_some());
    let parked_call_id = h
        .tool_agents
        .iter()
        .find_map(|(call_id, owner)| (owner == &side_cid).then(|| call_id.clone()))
        .expect("normalized side call remains live");
    let parked_side_agent = h.agents.get(&side_cid).expect("side agent remains parked");
    assert_eq!(parked_side_agent.tools_in_flight, 1);
    assert!(parked_side_agent.in_flight_prompt.is_none());
    assert!(!h.completed_tool_calls.contains(&parked_call_id));

    h.handle_extension_event(
        "side-invalid-terminal-interceptor",
        TestProtocolItem::Message(TestMessage::InterceptReply(InterceptReply {
            action: InterceptAction::Pass(None),
        })),
    )
    .expect("commit side canonical error");

    let side_agent = h.agents.get(&side_cid).expect("side agent remains loaded");
    let continuation = side_agent
        .in_flight_prompt
        .as_ref()
        .expect("automatic continuation remains in flight");
    assert_ne!(continuation, &first_prompt_id);
    assert!(matches!(
        side_agent.turn_state,
        AgentTurnState::AgentThinking { .. }
    ));
    assert_eq!(side_agent.tools_in_flight, 0);
    assert!(h.completed_tool_calls.contains(&parked_call_id));
    assert_eq!(
        event_log_events(&h)
            .into_iter()
            .filter(|event| matches!(
                event,
                Event::ProviderToolError(error) | Event::ToolError(error)
                    if error.call_id == parked_call_id
            ))
            .count(),
        2
    );
    assert!(!event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::SessionAgentUnloaded(unloaded)
            if unloaded.agent_id == durable_agent_id_for_conversation(&h, &side_cid)
    )));
}

/// A provider terminal that races after committed unload must consume stale
/// prompt correlation without publishing a response or panicking. Re-delivery
/// remains an idempotent duplicate.
#[test]
fn provider_completion_after_agent_unload_is_discarded_idempotently() {
    let td = TempDir::new().expect("tempdir");
    let sp = td.path().join("state");
    let mut h = echo_harness(&sp).expect("start");
    h.selected_model = Some("test/model".into());
    let cid = ensure_test_user_agent(&mut h);
    let prompt_id: AgentPromptId = test_agent_prompt_id("sp-late-after-unload");
    seed_agent_thinking(&mut h, &cid, prompt_id.as_str());
    h.prompt_agents.insert(prompt_id.clone(), cid.clone());
    let response = provider_text_response(
        &prompt_id,
        durable_agent_id_for_conversation(&h, &cid),
        "must be discarded",
    );

    h.remove_agent(&cid);
    assert!(!h.agents.contains_key(&cid));
    assert!(h.prompt_agents.contains_key(&prompt_id));

    h.handle_provider_response_finished(response.clone())
        .expect("late completion discarded");
    h.handle_provider_response_finished(response)
        .expect("duplicate late completion discarded");

    assert!(!h.prompt_agents.contains_key(&prompt_id));
    assert!(!event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::ProviderResponseFinished(finished)
            if finished.agent_prompt_id == prompt_id
    )));
    assert!(event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::HarnessNotice(notice)
            if notice.level == tau_proto::NoticeLevel::Info
                && notice.message.contains("after owner unload")
                && notice.message.contains(prompt_id.as_str())
    )));
}

