/// A physical post-accept creation failure terminalizes accepted requests
/// without exposing the failed identity while later FIFO work continues.
#[test]
fn accepted_start_storage_failure_terminalizes_and_continues_fifo() {
    let td = TempDir::new().expect("tempdir");
    let state = td.path().join("state");
    let mut h = quiet_provider_harness(&state).expect("harness");
    let first = h
        .prepare_start_agent_request(
            &crate::test_connection_id(HARNESS_CONNECTION_ID),
            ext_query("q-fail"),
        )
        .expect("prepare first")
        .expect("first pending");
    let second = h
        .prepare_start_agent_request(
            &crate::test_connection_id(HARNESS_CONNECTION_ID),
            ext_query("q-next"),
        )
        .expect("prepare second")
        .expect("second pending");
    let first_agent_id = first.agent_id.clone();
    let second_agent_id = second.agent_id.clone();
    h.accept_duplicate_start_agent_request(
        &crate::test_connection_id(HARNESS_CONNECTION_ID),
        &first.query.query_id,
        &first_agent_id,
    );
    h.accept_duplicate_start_agent_request(
        &crate::test_connection_id(HARNESS_CONNECTION_ID),
        &second.query.query_id,
        &second_agent_id,
    );
    h.pending_start_agent_requests.push_back(first);
    h.pending_start_agent_requests.push_back(second);
    let blocked_journal = state
        .join("agents")
        .join(&first_agent_id)
        .join("events.cbor");
    std::fs::create_dir_all(&blocked_journal).expect("block first journal");

    h.drain_pending_start_agent_requests().expect("drain");

    let events = event_log_events(&h);
    assert_eq!(
        events
            .iter()
            .filter(|event| matches!(
                event,
                Event::StartAgentAccepted(accepted) if accepted.query_id == "q-fail"
            ))
            .count(),
        1
    );
    let failed_results: Vec<_> = events
        .iter()
        .filter_map(|event| match event {
            Event::StartAgentResult(result) if result.query_id == "q-fail" => Some(result),
            _ => None,
        })
        .collect();
    assert_eq!(failed_results.len(), 1);
    assert!(failed_results[0].error.is_some());
    assert!(!h.agent_routes.contains_key(&first_agent_id));
    assert!(
        !h.agents
            .contains_key(&crate::parse_agent_id(&first_agent_id))
    );
    assert!(
        !h.session_loaded_agents
            .contains(&crate::parse_agent_id(&first_agent_id))
    );
    assert!(h.store.session("s1").is_none_or(|membership| {
        !membership.contains_agent(&crate::parse_agent_id(&first_agent_id))
    }));
    assert!(events.iter().all(|event| !matches!(
        event,
        Event::AgentPromptSubmitted(prompt) if prompt.agent_id.as_str() == first_agent_id
    )));
    assert!(events.iter().all(|event| !matches!(
        event,
        Event::AgentStarted(started) if started.agent_id.as_str() == first_agent_id
    )));
    assert!(events.iter().all(|event| !matches!(
        event,
        Event::SessionAgentLoaded(loaded) if loaded.agent_id.as_str() == first_agent_id
    )));
    assert!(h.agent_routes.contains_key(&second_agent_id));
    let second_records = h
        .agent_store
        .agent_events(&second_agent_id)
        .expect("second agent records");
    assert!(!second_records.is_empty());
    assert!(h.store.session("s1").is_some_and(|membership| {
        membership.contains_agent(&crate::parse_agent_id(&second_agent_id))
    }));
    assert_eq!(
        events
            .iter()
            .filter(|event| matches!(
                event,
                Event::StartAgentResult(result)
                    if result.query_id == "q-next" && result.error.is_none()
            ))
            .count(),
        0
    );
    assert!(events.iter().any(|event| matches!(
        event,
        Event::AgentStarted(started) if started.agent_id.as_str() == second_agent_id
    )));
    assert!(h.pending_start_agent_requests.is_empty());
}

fn provider_model_info(
    id: tau_proto::ModelId,
    context_window: u64,
) -> tau_proto::ProviderModelInfo {
    tau_proto::ProviderModelInfo {
        id,
        display_name: None,
        tags: Vec::new(),
        supported_tool_types: vec![],
        input_modalities: Vec::new(),
        tool_result_modalities: Vec::new(),
        supports_parallel_tool_calls: true,
        default_affinity: 0,
        context_window,
        efforts: vec![tau_proto::Effort::Off, tau_proto::Effort::High],
        verbosities: vec![tau_proto::Verbosity::Low, tau_proto::Verbosity::High],
        thinking_summaries: vec![
            tau_proto::ThinkingSummary::Off,
            tau_proto::ThinkingSummary::Auto,
        ],
        supports_compaction: false,
        supports_standalone_compaction: false,
        standalone_compaction_threshold: None,
        cache_policy: None,
        est_uncached_input_cost_1m_usd: Default::default(),
        est_cached_input_cost_1m_usd: Default::default(),
        est_cache_write_input_cost_1m_usd: Default::default(),
        est_output_cost_1m_usd: Default::default(),
        est_cache_storage_cost_1m_token_hour_usd: None,
    }
}

fn set_available_provider_models(
    h: &mut Harness,
    models: impl IntoIterator<Item = tau_proto::ProviderModelInfo>,
) {
    let models: Vec<_> = models.into_iter().collect();
    h.available_models = models.iter().map(|info| info.id.clone()).collect();
    h.provider_model_info = models
        .into_iter()
        .map(|info| (info.id.clone(), info))
        .collect();
}

fn ext_query_cid(h: &Harness, query_id: &str) -> Option<AgentId> {
    h.agents.iter().find_map(|(cid, conv)| {
        matches!(
            &conv.originator,
            tau_proto::PromptOriginator::Extension { query_id: id, .. } if id == query_id
        )
        .then_some(cid.clone())
    })
}

/// Regression: a backgrounded call remains tracked after its synthetic
/// placeholder closes the foreground, while later tool calls dispatch normally.
/// The real background result must clear only the actual-running state.
#[test]
fn background_result_clears_actual_running_call_without_blocking_later_tool() {
    let td = TempDir::new().expect("tempdir");
    let sp = td.path().join("state");
    let mut h = echo_harness(&sp).expect("start");
    h.selected_model = Some("test/model".into());

    let tool_events = connect_ready_configured_extension(
        &mut h,
        "conn-bg-result-drain",
        "configured-conn-bg-result-drain",
        tau_proto::ClientKind::Tool,
    );
    h.registry.register(
        &crate::test_connection_id("conn-bg-result-drain"),
        scheduled_test_tool_spec("bg_update", tau_proto::BackgroundSupport::Instant),
    );
    h.registry.register(
        &crate::test_connection_id("conn-bg-result-drain"),
        scheduled_test_tool_spec("queued_update", tau_proto::BackgroundSupport::Never),
    );

    let cid = ensure_test_user_agent(&mut h);
    let spid: AgentPromptId = test_agent_prompt_id("sp-bg-result-drain");
    seed_agent_thinking(&mut h, &cid, spid.as_str());
    h.prompt_agents.insert(spid.clone(), cid);
    h.handle_provider_response_finished(ProviderResponseFinished {
        estimated_api_cost_rates: None,
        estimated_api_cost_increment: None,

        agent_prompt_id: spid,
        agent_id: tau_proto::AgentId::parse("main").expect("agent id"),
        output_items: vec![
            ContextItem::ToolCall(ToolCallItem {
                call_id: "bg-update-running".into(),
                name: ToolName::new("bg_update"),
                tool_type: tau_proto::ToolType::Function,
                arguments: CborValue::Map(Vec::new()),
                raw_arguments_json: None,
                responses_envelope: None,
            }),
            ContextItem::ToolCall(ToolCallItem {
                call_id: "queued-update".into(),
                name: ToolName::new("queued_update"),
                tool_type: tau_proto::ToolType::Function,
                arguments: CborValue::Map(Vec::new()),
                raw_arguments_json: None,
                responses_envelope: None,
            }),
        ],
        stop_reason: tau_proto::ProviderStopReason::ToolCalls,
        error: None,
        failure_kind: None,
        context_limit_telemetry: None,
        recovery_disposition: tau_proto::ContextRecoveryDisposition::None,
        usage: None,
        originator: tau_proto::PromptOriginator::User,
        compaction_original_input_tokens: None,
        compaction_compacted_input_tokens: None,
        backend: None,
        provider_response_id: None,
        ws_pool_delta: None,
    })
    .expect("tool response");

    assert_eq!(
        tool_invoke_call_ids(&tool_events),
        vec!["bg-update-running".to_owned(), "queued-update".to_owned()]
    );
    assert_eq!(background_placeholder_count(&h, "bg-update-running"), 1);
    assert!(h.tool_turn.is_backgrounded(&"bg-update-running".into()));
    assert_eq!(h.tool_turn.pending_len(), 0);

    h.handle_extension_event_inner(
        &crate::test_connection_id("conn-bg-result-drain"),
        Event::ToolResultReported(final_tool_result(
            "bg-update-running",
            "bg_update",
            "background output",
        )),
    )
    .expect("background result accepted");

    assert_eq!(
        tool_invoke_call_ids(&tool_events),
        vec!["bg-update-running".to_owned(), "queued-update".to_owned()]
    );
    assert_eq!(background_result_count(&h, "bg-update-running"), 1);
    assert!(!h.tool_turn.is_backgrounded(&"bg-update-running".into()));
    assert_eq!(h.tool_turn.pending_len(), 0);
    assert!(!h.pending_tool_providers.contains_key("bg-update-running"));
    assert!(h.pending_tool_providers.contains_key("queued-update"));

    h.shutdown().expect("shutdown");
}

