/// Repeated ensure calls for an already-loaded agent are a hot-path no-op and
/// must not deserialize historical journals again.
#[test]
fn repeated_loaded_agent_ensure_does_not_rescan_history() {
    let td = TempDir::new().expect("tempdir");
    let state_dir = td.path().join("state");
    let mut h = quiet_provider_harness(&state_dir).expect("harness");
    let cid = ensure_test_user_agent(&mut h);
    let agent_id = durable_agent_id_for_conversation(&h, &cid);
    let notice_count = h.replayable_harness_notices.len();

    std::fs::write(
        state_dir
            .join("agents")
            .join(agent_id.as_str())
            .join("events.cbor"),
        b"corrupt after initial load",
    )
    .expect("corrupt journal");
    h.ensure_loaded_agent_for_agent(&cid, agent_id.as_str());

    assert_eq!(h.replayable_harness_notices.len(), notice_count);
    h.shutdown().expect("shutdown");
}

/// Regression: a cold-resumed session needs one hidden restore notice in the
/// first provider prompt, but startup itself must not send that notice as a
/// standalone turn or as prewarm-only context.
#[test]
fn resumed_startup_folds_restore_notice_before_first_user_prompt() {
    let td = TempDir::new().expect("tempdir");
    let sp = td.path().join("state");
    let two_hours_ago = tau_proto::UnixMicros::new(
        tau_proto::UnixMicros::now()
            .get()
            .saturating_sub(2 * 60 * 60 * 1_000_000),
    );
    seed_prior_user_message_at(&sp, "before restore", two_hours_ago);

    let mut h =
        quiet_provider_harness_with_start_reason(&sp, tau_proto::SessionStartReason::Resume)
            .expect("resume");

    assert!(h.prompt_agents.is_empty());
    assert!(!event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::AgentPromptCreated(_)
    )));
    assert!(!event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::AgentPromptPrewarmRequested(prewarm)
            if prewarm
                .context.flatten()
                .iter()
                .any(|item| text_part(item).is_some_and(|text| crate::internal_envelope::body(text).is_some_and(is_restore_notice_prompt_text)))
    )));
    assert_eq!(restore_notice_event_count(&h), 0);

    h.submit_user_prompt(test_session_id("s1"), "after restore".to_owned())
        .expect("submit first resumed prompt");
    let prompt = read_nth_prompt_created(&h, 0);
    let notice_pos = prompt
        .context
        .flatten()
        .iter()
        .position(|item| {
            text_part(item).is_some_and(|text| {
                crate::internal_envelope::body(text).is_some_and(is_restore_notice_prompt_text)
            })
        })
        .expect("restore notice in first prompt");
    let user_pos = prompt
        .context
        .flatten()
        .iter()
        .position(|item| text_part(item) == Some("after restore"))
        .expect("user prompt in first prompt");
    let notice = restore_notice_context_text(&prompt).expect("restore notice text");

    assert!(notice_pos < user_pos);
    assert!(notice.contains("Previous session was interrupted and restored."));
    assert!(notice.contains("2 hours have passed since the last recorded session event"));
    assert!(notice.contains("state of the world might have changed"));
    assert!(notice.contains("recreate timers"));
    assert_eq!(restore_notice_context_count(&prompt), 1);
    assert_eq!(restore_notice_event_count(&h), 1);

    h.shutdown().expect("shutdown");
}

/// Each new canonical activation committed before its first checkpoint is
/// replay-woken once.
#[test]
fn resume_dispatches_true_activation_without_first_checkpoint() {
    let agent_id = tau_proto::AgentId::parse("main").expect("agent id");
    let cases = [
        (
            "submitted activation",
            Event::AgentPromptSubmitted(tau_proto::AgentPromptSubmitted {
                inference_activation: true,
                agent_id: agent_id.clone(),
                text: "submitted activation".to_owned(),
                trusted_internal_spans: Vec::new(),
                message_class: tau_proto::PromptMessageClass::User,
                internal_kind: None,
                originator: tau_proto::PromptOriginator::User,
                submission_source: Default::default(),
                display_name: None,
                ctx_id: None,
            }),
        ),
        (
            "injected activation",
            Event::AgentUserMessageInjected(tau_proto::AgentUserMessageInjected {
                inference_activation: true,
                agent_id: agent_id.clone(),
                text: "injected activation".to_owned(),
                message_class: tau_proto::PromptMessageClass::Internal,
            }),
        ),
        (
            "steered activation",
            Event::AgentPromptSteered(tau_proto::AgentPromptSteered {
                self_compaction_terminal: None,
                inference_activation: true,
                submission_source: tau_proto::PromptSubmissionSource::HarnessInternal,
                agent_id,
                text: "steered activation".to_owned(),
                trusted_internal_spans: Vec::new(),
                message_class: tau_proto::PromptMessageClass::User,
                internal_kind: None,
                ctx_id: Some("ctx-1".to_owned()),
            }),
        ),
    ];

    for (text, event) in cases {
        let td = TempDir::new().expect("tempdir");
        let state = td.path().join("state");
        seed_inference_activation_event(&state, event);

        let mut h =
            quiet_provider_harness_with_start_reason(&state, tau_proto::SessionStartReason::Resume)
                .expect("resume");
        let prompt = read_nth_prompt_created(&h, 0);
        let context = serde_json::to_string(&prompt.context).expect("context");
        assert_eq!(context.matches(text).count(), 1);
        assert_eq!(
            event_log_events(&h)
                .into_iter()
                .filter(|event| matches!(event, Event::AgentInferenceDispatchStarted(_)))
                .count(),
            1
        );
        h.shutdown().expect("shutdown");
    }
}

/// Explicit-false canonical facts are passive transcript context and must not
/// independently wake inference during cold replay.
#[test]
fn resume_does_not_dispatch_false_canonical_facts() {
    let agent_id = tau_proto::AgentId::parse("main").expect("agent id");
    let cases = [
        Event::AgentPromptSubmitted(tau_proto::AgentPromptSubmitted {
            inference_activation: false,
            agent_id: agent_id.clone(),
            text: "passive submitted".to_owned(),
            trusted_internal_spans: Vec::new(),
            message_class: tau_proto::PromptMessageClass::Internal,
            internal_kind: None,
            originator: tau_proto::PromptOriginator::User,
            submission_source: Default::default(),
            display_name: None,
            ctx_id: None,
        }),
        Event::AgentUserMessageInjected(tau_proto::AgentUserMessageInjected {
            inference_activation: false,
            agent_id: agent_id.clone(),
            text: "passive injected".to_owned(),
            message_class: tau_proto::PromptMessageClass::Internal,
        }),
        Event::AgentPromptSteered(tau_proto::AgentPromptSteered {
            self_compaction_terminal: None,
            inference_activation: false,
            submission_source: tau_proto::PromptSubmissionSource::HarnessInternal,
            agent_id,
            text: "passive steered".to_owned(),
            trusted_internal_spans: Vec::new(),
            message_class: tau_proto::PromptMessageClass::Internal,
            internal_kind: None,
            ctx_id: None,
        }),
    ];

    for event in cases {
        let td = TempDir::new().expect("tempdir");
        let state = td.path().join("state");
        seed_inference_activation_event(&state, event);

        let mut h =
            quiet_provider_harness_with_start_reason(&state, tau_proto::SessionStartReason::Resume)
                .expect("resume");
        assert!(!event_log_contains_any_source(&h, |event| matches!(
            event,
            Event::AgentPromptCreated(_) | Event::AgentInferenceDispatchStarted(_)
        )));
        h.shutdown().expect("shutdown");
    }
}

/// Model-visible text cannot spoof harness-owned passive provenance: a normal
/// activating prompt remains active even when its bytes resemble a restore
/// notice.
#[test]
fn restore_looking_user_text_remains_an_activation() {
    let td = TempDir::new().expect("tempdir");
    let mut h = quiet_provider_harness(td.path()).expect("harness");
    let cid = ensure_test_user_agent(&mut h);
    let text = crate::harness::restore_notice_prompt_for_elapsed(None);

    h.dispatch_prompt_for_agent(&cid, PendingPrompt::human_ui(text.clone()))
        .expect("dispatch spoof-shaped user text");

    assert!(event_log_events(&h).into_iter().any(|event| matches!(
        event,
        Event::AgentPromptSubmitted(submitted)
            if submitted.text == text && submitted.inference_activation
    )));
    h.shutdown().expect("shutdown");
}

/// A completed checkpoint consumes every true activation through its head,
/// leaves a later true node pending once, and an uncompleted replacement
/// checkpoint restores as uncertain without redispatch. This guards
/// `SPEC-compaction-and-context-recovery`.
#[test]
fn replay_respects_activation_checkpoint_ranges_and_uncertainty() {
    let td = TempDir::new().expect("tempdir");
    let state = td.path().join("state");
    seed_main_agent_loaded(&state);
    let agent_id = tau_proto::AgentId::parse("main").expect("agent id");
    let mut store = tau_core::AgentStore::open(state.join("agents")).expect("agent store");
    for text in ["activation A", "activation B"] {
        append_seed_agent_event(
            &mut store,
            Event::AgentPromptSubmitted(tau_proto::AgentPromptSubmitted {
                inference_activation: true,
                agent_id: agent_id.clone(),
                text: text.to_owned(),
                trusted_internal_spans: Vec::new(),
                message_class: tau_proto::PromptMessageClass::User,
                internal_kind: None,
                originator: tau_proto::PromptOriginator::User,
                submission_source: Default::default(),
                display_name: None,
                ctx_id: None,
            }),
        );
    }
    let through = store
        .agent("main")
        .and_then(tau_core::AgentTree::head)
        .expect("second activation head");
    let completed_prompt_id = test_agent_prompt_id("ap-main-completed");
    append_seed_agent_event(
        &mut store,
        Event::AgentInferenceDispatchStarted(tau_proto::AgentInferenceDispatchStarted {
            agent_id: agent_id.clone(),
            transaction_id: None,
            agent_prompt_id: completed_prompt_id.clone(),
            through: tau_proto::AgentHead::Node(through),
            model: None,
            operation: None,
            activation_cut: None,
        }),
    );
    append_seed_agent_event(
        &mut store,
        Event::ProviderResponseFinished(provider_text_response(
            &completed_prompt_id,
            agent_id.clone(),
            "completed response",
        )),
    );
    append_seed_agent_event(
        &mut store,
        Event::AgentPromptSubmitted(tau_proto::AgentPromptSubmitted {
            inference_activation: true,
            agent_id,
            text: "activation C".to_owned(),
            trusted_internal_spans: Vec::new(),
            message_class: tau_proto::PromptMessageClass::User,
            internal_kind: None,
            originator: tau_proto::PromptOriginator::User,
            submission_source: Default::default(),
            display_name: None,
            ctx_id: None,
        }),
    );
    drop(store);

    let uncertain_prompt_id = {
        let mut h =
            quiet_provider_harness_with_start_reason(&state, tau_proto::SessionStartReason::Resume)
                .expect("first resume");
        let prompt = read_nth_prompt_created(&h, 0);
        let uncertain_prompt_id = prompt.agent_prompt_id.clone();
        let context = serde_json::to_string(&prompt.context).expect("context");
        assert_eq!(context.matches("activation C").count(), 1);
        assert_eq!(
            event_log_events(&h)
                .into_iter()
                .filter(|event| matches!(event, Event::AgentInferenceDispatchStarted(_)))
                .count(),
            1,
            "later activation should be checkpointed exactly once"
        );
        h.shutdown().expect("shutdown");
        uncertain_prompt_id
    };

    let mut h =
        quiet_provider_harness_with_start_reason(&state, tau_proto::SessionStartReason::Resume)
            .expect("uncertain resume");
    assert!(!event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::AgentPromptCreated(_) | Event::AgentInferenceDispatchStarted(_)
    )));
    let uncertain = h
        .agent_watch_provider_status
        .get("main")
        .expect("restored uncertain watcher snapshot");
    assert!(matches!(
        uncertain.state,
        tau_proto::AgentWatchProviderState::DispatchUncertain {
            category: tau_proto::AgentWatchProviderCategory::Unknown
        }
    ));
    assert_eq!(uncertain.agent_prompt_id, uncertain_prompt_id);
    h.shutdown().expect("shutdown");
}

/// The restore notice is a one-shot durable fact. Follow-up prompts and later
/// cold resumes may replay the original notice in history, but must not append
/// another copy.
#[test]
fn restore_notice_is_not_duplicated_by_followups_or_later_resumes() {
    let td = TempDir::new().expect("tempdir");
    let sp = td.path().join("state");
    seed_prior_user_message(&sp, "before restore");

    let notice = {
        let mut h =
            quiet_provider_harness_with_start_reason(&sp, tau_proto::SessionStartReason::Resume)
                .expect("first resume");

        h.submit_user_prompt(test_session_id("s1"), "first after restore".to_owned())
            .expect("submit first resumed prompt");
        let first_prompt = read_nth_prompt_created(&h, 0);
        let first_spid = first_prompt.agent_prompt_id.clone();
        let notice = restore_notice_context_text(&first_prompt)
            .expect("restore notice")
            .to_owned();
        assert_eq!(restore_notice_context_count(&first_prompt), 1);

        h.handle_provider_response_finished(provider_text_response(
            &first_spid,
            first_prompt.agent_id.clone(),
            "first answer",
        ))
        .expect("finish first prompt");
        h.submit_user_prompt(test_session_id("s1"), "second after restore".to_owned())
            .expect("submit second prompt");
        let second_prompt = read_nth_prompt_created(&h, 1);
        assert_eq!(context_text_count(&second_prompt, notice.as_str()), 1);
        assert_eq!(restore_notice_context_count(&second_prompt), 1);
        assert_eq!(restore_notice_event_count(&h), 1);
        h.handle_provider_response_finished(provider_text_response(
            &second_prompt.agent_prompt_id,
            second_prompt.agent_id.clone(),
            "second answer",
        ))
        .expect("finish second prompt before cold resume");

        h.shutdown().expect("shutdown");
        notice
    };
    wait_for_session_unlock(&sp, "s1");

    {
        let mut h =
            quiet_provider_harness_with_start_reason(&sp, tau_proto::SessionStartReason::Resume)
                .expect("second resume");

        h.submit_user_prompt(test_session_id("s1"), "third after restore".to_owned())
            .expect("submit after second resume");
        let prompt = read_nth_prompt_created(&h, 0);
        assert_eq!(context_text_count(&prompt, notice.as_str()), 1);
        assert_eq!(restore_notice_context_count(&prompt), 1);
        assert_eq!(restore_notice_event_count(&h), 1);

        h.shutdown().expect("shutdown");
    }
}

/// Regression: a background placeholder without a later background result/error
/// means the real tool was lost across cold restore. Resume must publish a
/// durable background error, fold an internal interruption note before the next
/// user prompt, and let `wait` consume the restored error instead of hanging.
#[test]
fn resumed_lost_background_tool_gets_error_and_wait_returns() {
    let td = TempDir::new().expect("tempdir");
    let sp = td.path().join("state");
    seed_background_placeholder(&sp, "lost-bg", "slow_bg");

    let mut h =
        quiet_provider_harness_with_start_reason(&sp, tau_proto::SessionStartReason::Resume)
            .expect("resume");
    let notice = restored_background_notice("lost-bg");

    assert_eq!(background_error_count(&h, "lost-bg"), 1);
    assert!(event_log_contains(
        &h,
        HARNESS_CONNECTION_ID,
        |event| matches!(
            event,
            Event::ToolBackgroundError(error)
                if error.call_id.as_str() == "lost-bg" && error.message == notice
        )
    ));
    assert!(!event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::AgentPromptCreated(_)
    )));

    h.submit_user_prompt(test_session_id("s1"), "after restore".to_owned())
        .expect("submit first resumed prompt");
    let first_prompt = read_nth_prompt_created(&h, 0);
    let first_spid = first_prompt.agent_prompt_id.clone();
    let notice_pos = first_prompt
        .context
        .flatten()
        .iter()
        .position(|item| text_part(item) == Some(crate::internal_envelope::frame(&notice).as_str()))
        .expect("background interruption notice in first prompt");
    let user_pos = first_prompt
        .context
        .flatten()
        .iter()
        .position(|item| text_part(item) == Some("after restore"))
        .expect("user prompt in first prompt");
    assert!(notice_pos < user_pos);

    h.handle_provider_response_finished(ProviderResponseFinished {
        estimated_api_cost_rates: None,
        estimated_api_cost_increment: None,

        agent_prompt_id: first_spid,
        agent_id: first_prompt.agent_id.clone(),
        output_items: vec![ContextItem::ToolCall(ToolCallItem {
            call_id: "wait-lost-bg".into(),
            name: ToolName::new("wait"),
            tool_type: tau_proto::ToolType::Function,
            arguments: CborValue::Map(vec![(
                CborValue::Text("tool_call_id".to_owned()),
                CborValue::Text("lost-bg".to_owned()),
            )]),
            raw_arguments_json: None,
            responses_envelope: None,
        })],
        stop_reason: tau_proto::ProviderStopReason::ToolCalls,
        error: None,
        failure_kind: None,
        context_limit_telemetry: None,
        recovery_disposition: tau_proto::ContextRecoveryDisposition::None,
        usage: None,
        originator: tau_proto::PromptOriginator::User,
        compaction_original_input_tokens: None,
        compaction_compacted_input_tokens: None,
        backend: None,
        provider_response_id: None,
        ws_pool_delta: None,
    })
    .expect("wait for restored background call");

    assert!(event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::ToolError(error)
            if error.call_id.as_str() == "wait-lost-bg" && error.message == notice
    )));

    h.shutdown().expect("shutdown");
}

/// Regression: restored background notices are owned by the agent whose
/// background call was repaired. A session-level queue let the first prompted
/// agent consume every restored background notice, including notices for other
/// loaded agents in the same session.
#[test]
fn restored_background_notices_are_delivered_to_owning_agent() {
    let td = TempDir::new().expect("tempdir");
    let sp = td.path().join("state");
    seed_background_placeholder_for_agent(&sp, "main", "main-lost-bg", "slow_bg");
    seed_background_placeholder_for_agent(&sp, "side_agent", "side-lost-bg", "slow_bg");

    let mut h =
        quiet_provider_harness_with_start_reason(&sp, tau_proto::SessionStartReason::Resume)
            .expect("resume");
    let main_notice = restored_background_notice("main-lost-bg");
    let side_notice = restored_background_notice("side-lost-bg");
    let main_cid = h
        .agent_routes
        .get("main")
        .cloned()
        .expect("main agent route");
    let side_cid = h
        .agent_routes
        .get("side_agent")
        .cloned()
        .expect("side agent route");

    let side_prompts = h.take_pending_restore_prompts_for_user_prompt(&side_cid);
    assert!(
        side_prompts.iter().any(|prompt| prompt.text == side_notice),
        "side agent should receive its own restored background notice"
    );
    assert!(
        side_prompts.iter().all(|prompt| prompt.text != main_notice),
        "side agent must not receive main agent's restored background notice"
    );

    let main_prompts = h.take_pending_restore_prompts_for_user_prompt(&main_cid);
    assert!(
        main_prompts.iter().any(|prompt| prompt.text == main_notice),
        "main agent should still receive its own restored background notice"
    );
    assert!(
        main_prompts.iter().all(|prompt| prompt.text != side_notice),
        "main agent must not receive side agent's restored background notice"
    );

    h.shutdown().expect("shutdown");
}

/// Resume should treat existing background results/errors as terminal. They are
/// replayed into the wait tracker, but no restored interruption error is
/// appended over the real outcome.
#[test]
fn resume_keeps_existing_background_completions() {
    let td = TempDir::new().expect("tempdir");
    let sp = td.path().join("state");
    seed_background_placeholder(&sp, "finished-bg", "slow_bg");
    seed_background_placeholder(&sp, "failed-bg", "slow_bg");
    seed_background_result(&sp, "finished-bg", "slow_bg", "finished");
    seed_background_error(&sp, "failed-bg", "slow_bg", "real failure");

    let mut h =
        quiet_provider_harness_with_start_reason(&sp, tau_proto::SessionStartReason::Resume)
            .expect("resume");

    assert_eq!(background_result_count(&h, "finished-bg"), 1);
    assert_eq!(background_error_count(&h, "finished-bg"), 0);
    assert_eq!(background_error_count(&h, "failed-bg"), 1);
    assert!(!event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::ToolBackgroundError(error)
            if error.message == restored_background_notice(error.call_id.as_str())
    )));

    h.shutdown().expect("shutdown");
}

