/// Session rollover commits the old shutdown, cancels a parked standalone
/// continuation checkpoint and all warm activation owners, suspends its
/// responder until the stale reply is consumed, and creates fresh routing only
/// on the next prompt.
#[test]
fn switch_session_clears_loaded_agents_until_next_prompt() {
    let td = TempDir::new().expect("tempdir");
    let sp = td.path().join("state");
    let mut h = echo_harness(&sp).expect("start"); // bound to "s1"
    h.selected_model = Some("test/model".into());
    let model: tau_proto::ModelId = "test/model".into();
    h.current_session_state.context_input_tokens = Some(92_000);
    h.current_session_state.context_cached_tokens = Some(90_000);
    h.current_session_state.context_percent_used = Some(92);
    h.current_session_state.token_usage.start_request(&model);
    h.current_session_state
        .token_usage
        .add_sent(&model, 819_300, 750_000);
    h.current_session_state
        .token_usage
        .add_received(&model, 34_000);

    let cid = ensure_test_user_agent(&mut h);
    assert_eq!(h.agents[&cid].session_id.as_str(), "s1");
    h.agents
        .get_mut(&cid)
        .expect("default conversation")
        .agent_id = Some("old-agent".to_owned());
    h.agent_routes.insert("old-agent".to_owned(), cid.clone());
    let transaction_id =
        tau_proto::CompactionTransactionId::parse("ct-session-reset").expect("transaction");
    h.pending_agent_publish_completions.insert(
        cid.clone(),
        AgentPublishCompletion::StandaloneContinuation {
            transaction_id: transaction_id.clone(),
            model: model.clone(),
            activation_cut: tau_proto::AgentHead::Root,
            batch_parent: tau_proto::AgentHead::Root,
            source: None,
            retry_prompts: vec![PendingPrompt::user("stale retry".to_owned())],
            complete_on_commit: true,
            approved_retry_event: None,
        },
    );
    h.enqueued_standalone_inference_checkpoints.insert((
        tau_proto::AgentId::parse("old-agent").expect("agent id"),
        transaction_id.clone(),
    ));
    h.enqueue_committed_activation_dispatch(
        cid.clone(),
        Some(tau_proto::AgentHead::Root),
        Some(tau_proto::AgentHead::Root),
    );
    let _interceptor = connect_test_tool(&mut h, "rollover-completion-owner");
    h.handle_extension_event(
        "rollover-completion-owner",
        TestProtocolItem::Message(TestMessage::Intercept(Intercept {
            selectors: vec![EventSelector::Exact(
                tau_proto::EventName::AGENT_INFERENCE_DISPATCH_STARTED,
            )],
            priority: InterceptionPriority::new(0),
        })),
    )
    .expect("register rollover interceptor");
    let checkpoint_prompt_id = test_agent_prompt_id("ap-old-checkpoint");
    h.agents
        .get_mut(&cid)
        .expect("old agent")
        .activation_dispatch = path_crate_agent::ActivationDispatchState::AwaitingCheckpoint {
        owner: path_crate_agent::InferenceCheckpointOwner::Standalone {
            id: transaction_id.clone(),
        },
        agent_prompt_id: checkpoint_prompt_id.clone(),
        through: tau_proto::AgentHead::Root,
        dispatch: crate::agent::InferenceDispatchOwnership {
            model: model.clone(),
            operation: tau_proto::PromptOperation::Inference,
            activation_cut: tau_proto::AgentHead::Root,
        },
    };
    h.publish_for_agent(
        &cid,
        Event::AgentInferenceDispatchStarted(tau_proto::AgentInferenceDispatchStarted {
            agent_id: tau_proto::AgentId::parse("old-agent").expect("agent id"),
            transaction_id: Some(transaction_id.clone()),
            agent_prompt_id: checkpoint_prompt_id,
            through: tau_proto::AgentHead::Root,
            model: Some(model.clone()),
            operation: Some(tau_proto::PromptOperation::Inference),
            activation_cut: Some(tau_proto::AgentHead::Root),
        }),
    );
    assert!(h.pending_intercept.is_some());

    let shell_conn = h
        .extension_connection_id("shell")
        .expect("shell")
        .to_owned();

    h.switch_session(test_session_id("s2"), tau_proto::SessionStartReason::New)
        .expect("switch");

    let mut saw_session_dir = false;
    let mut cursor = path_crate_event_log::EventLogSeq::new(0);
    while let Some(entry) = h.event_log.get_next_from(cursor) {
        cursor = entry.seq.next();
        if let Event::HarnessSessionDir(session_dir) = &entry.event
            && session_dir.session_id == "s2"
            && session_dir.path.ends_with("s2")
            && session_dir.status == tau_proto::SessionDirStatus::New
        {
            saw_session_dir = true;
        }
    }
    assert!(saw_session_dir, "switch must announce the new session dir");

    assert_eq!(h.current_session_id.as_str(), "s2");
    assert!(h.pending_agent_publish_completions.is_empty());
    assert!(h.enqueued_standalone_inference_checkpoints.is_empty());
    assert!(h.pending_publish_idle_dispatches.is_empty());
    assert!(h.pending_intercept.is_none());
    assert!(event_log_events(&h).into_iter().any(|event| {
        matches!(
            event,
            Event::SessionShutdown(shutdown) if shutdown.session_id.as_str() == "s1"
        )
    }));
    assert!(!event_log_events(&h).into_iter().any(|event| {
        matches!(
            event,
            Event::AgentInferenceDispatchStarted(started)
                if started.transaction_id.as_ref() == Some(&transaction_id)
        )
    }));
    h.handle_extension_event(
        "rollover-completion-owner",
        TestProtocolItem::Message(TestMessage::Intercept(Intercept {
            selectors: vec![EventSelector::Exact(tau_proto::EventName::UI_PROMPT_DRAFT)],
            priority: InterceptionPriority::new(0),
        })),
    )
    .expect("replace suspended interceptor registration");
    let new_session_draft = Event::UiPromptDraft(tau_proto::UiPromptDraft {
        session_id: test_session_id("s2"),
        target_agent_id: None,
        text: Some("new session event".to_owned()),
    });
    h.publish_event(None, new_session_draft.clone());
    assert!(h.pending_intercept.is_none());
    h.handle_extension_event(
        "rollover-completion-owner",
        TestProtocolItem::Message(TestMessage::InterceptReply(InterceptReply {
            action: InterceptAction::Drop,
        })),
    )
    .expect("stale old-session reply is ignored");
    assert!(event_log_events(&h).contains(&new_session_draft));
    let post_stale_draft = Event::UiPromptDraft(tau_proto::UiPromptDraft {
        session_id: test_session_id("s2"),
        target_agent_id: None,
        text: Some("interception resumes after stale reply".to_owned()),
    });
    h.publish_event(None, post_stale_draft.clone());
    assert!(h.pending_intercept.is_some());
    h.handle_extension_event(
        "rollover-completion-owner",
        TestProtocolItem::Message(TestMessage::InterceptReply(InterceptReply {
            action: InterceptAction::Pass(None),
        })),
    )
    .expect("registration resumes after stale reply is consumed");
    assert!(event_log_events(&h).contains(&post_stale_draft));
    assert_eq!(h.current_session_state.context_input_tokens, None);
    assert_eq!(h.current_session_state.context_cached_tokens, None);
    assert_eq!(h.current_session_state.context_percent_used, None);
    assert_eq!(
        h.current_session_state.token_usage,
        tau_proto::TokenUsageStats::default()
    );
    assert!(h.agents.is_empty());
    assert!(h.agent_routes.is_empty());

    // Drive the new session through init so submit_user_prompt
    // actually dispatches (rather than queuing).
    h.handle_extension_event(
        &shell_conn,
        TestProtocolItem::Event(Event::ExtensionContextReady(
            tau_proto::ExtensionContextReady {
                agent_initialization_id: tau_proto::AgentInitializationId::parse("test-init")
                    .expect("test identifier must be valid"),

                session_id: test_session_id("s2"),
                agent_id: tau_proto::AgentId::parse("agent-1").expect("agent id"),
            },
        )),
    )
    .expect("ready");

    let submission = h
        .submit_user_prompt(test_session_id("s2"), "hello".to_owned())
        .expect("submit");
    assert_eq!(submission, PromptSubmission::Dispatched);
    let new_cid = test_user_agent(&h);
    let new_agent_id = h.agents[&new_cid]
        .agent_id
        .clone()
        .expect("new session agent id");
    publish_pending_agent_discovery(&mut h, new_agent_id.as_str());
    assert!(read_nth_prompt_created(&h, 0).agent_id.as_str() == new_agent_id);

    h.shutdown().expect("shutdown");
}

#[test]
fn manual_compact_appends_trigger_and_dispatches_normal_prompt() {
    let td = TempDir::new().expect("tempdir");
    let sp = td.path().join("state");
    let mut h = quiet_provider_harness(&sp).expect("start");
    enable_remote_compaction_for_test_model(&mut h);

    let cid = ensure_test_user_agent(&mut h);
    let target_agent_id = h.agents[&cid].agent_id.clone().expect("durable agent id");
    let selected_role = h.selected_role.clone();
    h.available_roles
        .get_mut(&selected_role)
        .expect("selected role")
        .compaction = Some(path_tau_config_settings::RoleCompaction::Threshold(1200));

    h.handle_compact_request(test_session_id("s1"), Some(&target_agent_id));

    assert!(event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::AgentCompactionTriggered(triggered)
            if triggered.agent_id.as_str() == target_agent_id.as_str()
    )));
    let mut cursor = path_crate_event_log::EventLogSeq::new(0);
    let mut prompt = None;
    while let Some(entry) = h.event_log.get_next_from(cursor) {
        cursor = entry.seq.next();
        if let Event::AgentPromptCreated(created) = entry.event {
            prompt = Some(created);
        }
    }
    let prompt = prompt.expect("normal prompt created");
    assert!(
        prompt
            .context
            .flatten()
            .contains(&ContextItem::CompactionTrigger)
    );
    assert_eq!(
        prompt.compaction,
        Some(tau_proto::PromptCompactionContext {
            compact_threshold: Some(1200),
        })
    );

    h.shutdown().expect("shutdown");
}

/// Named context-size alerts fire as internal prompts only after their
/// thresholds are exceeded, remain one-shot while usage stays high, and become
/// eligible again after usage falls back below the threshold.
#[test]
fn named_context_size_alerts_queue_once_per_usage_crossing() {
    let td = TempDir::new().expect("tempdir");
    let mut h = quiet_provider_harness(td.path().join("state")).expect("start");
    let cid = ensure_test_user_agent(&mut h);
    let role = h
        .available_roles
        .get_mut(&h.selected_role)
        .expect("selected role");
    role.context_size_alerts.insert(
        "compact-soon".to_owned(),
        tau_config::settings::ContextSizeAlert {
            threshold: 100,
            enable: true,
            message: "compact soon".to_owned(),
        },
    );
    role.context_size_alerts.insert(
        "later".to_owned(),
        tau_config::settings::ContextSizeAlert {
            threshold: 200,
            enable: true,
            message: "compact now".to_owned(),
        },
    );
    role.context_size_alerts.insert(
        "disabled".to_owned(),
        tau_config::settings::ContextSizeAlert {
            threshold: 1,
            enable: false,
            message: "must not appear".to_owned(),
        },
    );
    let alerts = role.context_size_alerts.clone();

    h.queue_crossed_context_size_alerts(&cid, Some(100), &alerts);
    assert!(h.agents[&cid].pending_prompts.is_empty());

    h.queue_crossed_context_size_alerts(&cid, Some(250), &alerts);
    let prompts = h.agents[&cid]
        .pending_prompts
        .iter()
        .map(|prompt| (prompt.text.as_str(), prompt.message_class))
        .collect::<Vec<_>>();
    assert_eq!(
        prompts,
        vec![
            ("compact soon", tau_proto::PromptMessageClass::Internal),
            ("compact now", tau_proto::PromptMessageClass::Internal),
        ]
    );

    h.queue_crossed_context_size_alerts(&cid, Some(300), &alerts);
    assert_eq!(h.agents[&cid].pending_prompts.len(), 2);
    h.queue_crossed_context_size_alerts(&cid, Some(50), &alerts);
    h.queue_crossed_context_size_alerts(&cid, Some(250), &alerts);
    assert_eq!(h.agents[&cid].pending_prompts.len(), 4);
    h.clear_agent_context_usage(&cid);
    assert!(h.agents[&cid].pending_prompts.is_empty());
    h.queue_crossed_context_size_alerts(&cid, Some(250), &alerts);
    assert_eq!(h.agents[&cid].pending_prompts.len(), 2);

    h.shutdown().expect("shutdown");
}

/// A finished ordinary response with usage above an alert threshold must route
/// the configured text through the normal durable internal-prompt path.
#[test]
fn finished_response_injects_crossed_context_size_alert() {
    let td = TempDir::new().expect("tempdir");
    let mut h = quiet_provider_harness(td.path().join("state")).expect("start");
    let cid = ensure_test_user_agent(&mut h);
    h.available_roles
        .get_mut(&h.selected_role)
        .expect("selected role")
        .context_size_alerts
        .insert(
            "compact-soon".to_owned(),
            tau_config::settings::ContextSizeAlert {
                threshold: 100,
                enable: true,
                message: "compact after this task".to_owned(),
            },
        );

    h.dispatch_prompt_for_agent(&cid, PendingPrompt::user("work".to_owned()))
        .expect("dispatch");
    let prompt = read_nth_prompt_created(&h, 0);
    let mut response =
        provider_text_response(&prompt.agent_prompt_id, prompt.agent_id, "finished work");
    response.usage = Some(tau_proto::ProviderTokenUsage {
        model: None,
        prompt_sent_tokens: 101,
        prompt_cached_tokens: 0,
        prompt_cache_read_ceiling_tokens: None,
        cache: None,
        response_received_tokens: 2,
        stats: Default::default(),
    });
    h.handle_provider_response_finished(response)
        .expect("finish response");

    let alert_prompt = read_nth_prompt_created(&h, 1);
    let events = event_log_events(&h);
    let response_index = events
        .iter()
        .position(|event| {
            matches!(
                event,
                Event::ProviderResponseFinished(finished)
                    if finished.agent_prompt_id == prompt.agent_prompt_id
            )
        })
        .expect("threshold-crossing response");
    let alert_index = events
        .iter()
        .position(|event| {
            matches!(
                event,
                Event::AgentPromptSubmitted(submitted)
                    if submitted.text == "compact after this task"
                        && submitted.message_class == tau_proto::PromptMessageClass::Internal
                        && submitted.internal_kind
                            == Some(tau_proto::InternalPromptKind::ContextSizeAlert)
            )
        })
        .expect("durable context-size alert");
    let dispatch_index = events
        .iter()
        .position(|event| {
            matches!(
                event,
                Event::AgentPromptCreated(created)
                    if created.agent_prompt_id == alert_prompt.agent_prompt_id
            )
        })
        .expect("alert provider dispatch");
    assert!(
        response_index < alert_index && alert_index < dispatch_index,
        "alert delivery fact must land after the crossing response and before its provider dispatch"
    );
    h.shutdown().expect("shutdown");
}

/// Alert policy belongs to the dispatched prompt, so changing the interactive
/// role while the provider is running cannot substitute another role's message.
#[test]
fn context_size_alert_uses_prompt_owned_role_snapshot() {
    let td = TempDir::new().expect("tempdir");
    let mut h = quiet_provider_harness(td.path().join("state")).expect("start");
    let cid = ensure_test_user_agent(&mut h);
    h.available_roles
        .get_mut(&h.selected_role)
        .expect("selected role")
        .context_size_alerts
        .insert(
            "compact-soon".to_owned(),
            tau_config::settings::ContextSizeAlert {
                threshold: 100,
                enable: true,
                message: "original role alert".to_owned(),
            },
        );
    h.dispatch_prompt_for_agent(&cid, PendingPrompt::user("work".to_owned()))
        .expect("dispatch");
    let prompt = read_nth_prompt_created(&h, 0);

    let mut replacement_role = path_tau_config_settings::AgentRole::default();
    replacement_role.context_size_alerts.insert(
        "compact-soon".to_owned(),
        tau_config::settings::ContextSizeAlert {
            threshold: 1,
            enable: true,
            message: "replacement role alert".to_owned(),
        },
    );
    h.available_roles
        .insert("replacement".to_owned(), replacement_role);
    h.selected_role = "replacement".to_owned();

    let mut response =
        provider_text_response(&prompt.agent_prompt_id, prompt.agent_id, "finished work");
    response.usage = Some(tau_proto::ProviderTokenUsage {
        model: None,
        prompt_sent_tokens: 101,
        prompt_cached_tokens: 0,
        prompt_cache_read_ceiling_tokens: None,
        cache: None,
        response_received_tokens: 2,
        stats: Default::default(),
    });
    h.handle_provider_response_finished(response)
        .expect("finish response");

    assert!(event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::AgentPromptSubmitted(submitted) if submitted.text == "original role alert"
    )));
    assert!(!event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::AgentPromptSubmitted(submitted) if submitted.text == "replacement role alert"
    )));
    h.shutdown().expect("shutdown");
}

