/// Provider diagnostics must come from the provider that owns the prompt route.
#[test]
fn provider_cache_miss_diagnostic_requires_prompt_owner() {
    let td = TempDir::new().expect("tempdir");
    let sp = td.path().join("state");
    let mut h = echo_harness(&sp).expect("start");
    connect_ready_configured_extension(
        &mut h,
        "provider-a",
        "provider-a",
        tau_proto::ClientKind::Provider,
    );
    connect_ready_configured_extension(
        &mut h,
        "provider-b",
        "provider-b",
        tau_proto::ClientKind::Provider,
    );
    h.pending_provider_prompts.insert(
        test_agent_prompt_id("prompt-1"),
        crate::test_connection_id("provider-a"),
    );

    let baseline_seq = h.event_log.next_seq();
    h.handle_extension_message(
        &crate::test_connection_id("provider-b"),
        TestMessage::Emit(tau_proto::Emit {
            event: Box::new(Event::ProviderCacheMissDiagnosticReported(
                cache_miss_diagnostic_for_test("prompt-1"),
            )),
            persist: true,
        }),
    )
    .expect("non-owner diagnostic emit");
    assert!(matches!(
        h.event_log
            .get_next_from(baseline_seq)
            .map(|entry| entry.event),
        Some(Event::ProviderCacheMissDiagnosticReported(_))
    ));
    assert!(!event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::ProviderCacheMissDiagnostic(_)
    )));

    h.handle_extension_message(
        &crate::test_connection_id("provider-a"),
        TestMessage::Emit(tau_proto::Emit {
            event: Box::new(Event::ProviderCacheMissDiagnosticReported(
                cache_miss_diagnostic_for_test("prompt-1"),
            )),
            persist: true,
        }),
    )
    .expect("owner diagnostic emit");
    assert!(event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::ProviderCacheMissDiagnostic(diagnostic)
            if diagnostic.agent_prompt_id.as_str() == "prompt-1"
    )));

    h.shutdown().expect("shutdown");
}

#[test]
fn tool_group_overrides_apply_before_individual_tool_overrides() {
    // Role group toggles are coarse-grained defaults. Individual tool toggles
    // must run after them so a role can enable a whole group and exclude one
    // dangerous tool, or disable a group and keep one explicit exception.
    let td = TempDir::new().expect("tempdir");
    let sp = td.path().join("state");
    let mut h = echo_harness(&sp).expect("start");
    h.available_roles.insert(
        h.selected_role.clone(),
        tau_config::settings::AgentRole {
            enable_tool_groups: vec![tau_proto::ToolGroupName::new("pim")],
            disable_tools: vec![ToolName::new("email_trash")],
            disable_tool_groups: vec![tau_proto::ToolGroupName::new("shell")],
            enable_tools: vec![ToolName::new("shell_safe")],
            ..Default::default()
        },
    );

    for (name, group) in [
        ("email_read", "pim"),
        ("email_trash", "pim"),
        ("shell_exec", "shell"),
        ("shell_safe", "shell"),
    ] {
        h.registry.register_with_prompt_fragment(
            &crate::test_connection_id("conn-grouped"),
            tau_core::ToolRegistration {
                tool: ToolSpec {
                    name: ToolName::new(name),
                    model_visible_name: None,
                    description: Some(name.to_owned()),
                    tool_type: tau_proto::ToolType::Function,
                    parameters: None,
                    format: None,
                    tags: Vec::new(),
                    enabled_by_default: false,
                    background_support: None,
                    examples: Vec::new(),
                },
                tool_group: Some(tau_proto::ToolGroup {
                    name: tau_proto::ToolGroupName::new(group),
                    prompt_fragment: (name == "email_trash").then(|| {
                        tau_proto::PromptFragment::new(
                            format!("{group}.instructions"),
                            tau_proto::PromptPriority::new(10),
                            format!("{group} GROUP PROMPT"),
                        )
                    }),
                }),
                prompt_fragment: None,
            },
        );
    }

    let defs = h.gather_tool_definitions_for_role(&h.selected_role);
    let names = defs.iter().map(|def| def.name.as_str()).collect::<Vec<_>>();
    assert!(
        names.contains(&"email_read"),
        "expected group-enabled tool: {names:?}"
    );
    assert!(
        !names.contains(&"email_trash"),
        "individual disable must win: {names:?}"
    );
    assert!(
        !names.contains(&"shell_exec"),
        "group disable should hide tool: {names:?}"
    );
    assert!(
        names.contains(&"shell_safe"),
        "individual enable must win: {names:?}"
    );
    let prompt_fragments = h.gather_prompt_fragments();
    let pim_group_prompts = prompt_fragments
        .iter()
        .filter(|fragment| fragment.template.as_str() == "pim GROUP PROMPT")
        .count();
    assert_eq!(pim_group_prompts, 1, "group prompt renders once");
}

/// Internal extension prompt submissions must stay hidden while still producing
/// harness-owned prompt facts for timer and other wakeup extensions.
#[test]
fn extension_internal_prompt_submit_request_routes_as_internal_prompt() {
    let td = TempDir::new().expect("tempdir");
    let sp = td.path().join("state");
    let mut h = echo_harness(&sp).expect("harness");
    connect_ready_configured_extension(
        &mut h,
        "utils-ext",
        "utils-ext",
        tau_proto::ClientKind::Tool,
    );
    h.selected_model = Some("test/model".into());
    let cid = ensure_test_user_agent(&mut h);
    let agent_id = durable_agent_id_for_conversation(&h, &cid);

    h.handle_extension_event(
        "utils-ext",
        TestProtocolItem::Event(Event::ExtInternalPromptSubmitRequest(
            tau_proto::ExtInternalPromptSubmitRequest {
                agent_id: agent_id.clone(),
                text: "timer fired".to_owned(),
                ctx_id: Some("timer:wake:1".to_owned()),
                activation_kind: None,
            },
        )),
    )
    .expect("submit internal prompt request");

    assert!(event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::AgentPromptSubmitted(prompt)
            if prompt.agent_id == agent_id
                && prompt.text == "timer fired"
                && prompt.message_class == tau_proto::PromptMessageClass::Internal
                && prompt.submission_source
                    == tau_proto::PromptSubmissionSource::Extension {
                        name: tau_proto::ExtensionName::parse("utils-ext")
                            .expect("configured extension name"),
                    }
                && prompt.ctx_id.as_deref() == Some("timer:wake:1")
    )));

    h.shutdown().expect("shutdown");
}

/// Bad extension prompt targets must be rejected with user-visible harness
/// notice and must not create durable prompt facts for arbitrary agent ids.
#[test]
fn extension_internal_prompt_submit_request_rejects_unknown_agent() {
    let td = TempDir::new().expect("tempdir");
    let sp = td.path().join("state");
    let mut h = echo_harness(&sp).expect("harness");
    connect_ready_configured_extension(
        &mut h,
        "utils-ext",
        "utils-ext",
        tau_proto::ClientKind::Tool,
    );

    h.handle_extension_event(
        "utils-ext",
        TestProtocolItem::Event(Event::ExtInternalPromptSubmitRequest(
            tau_proto::ExtInternalPromptSubmitRequest {
                agent_id: tau_proto::AgentId::parse("missing-agent").expect("agent id"),
                text: "hello".to_owned(),
                ctx_id: None,
                activation_kind: None,
            },
        )),
    )
    .expect("reject prompt request");

    assert!(event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::HarnessNotice(info) if info.message.contains("unknown or unloaded agent")
    )));
    assert!(!event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::AgentPromptSubmitted(prompt) if prompt.text == "hello"
    )));

    h.shutdown().expect("shutdown");
}

/// Queued extension internal-prompt requests preserve their ctx_id when they
/// are folded as steering messages, giving timer restore replayable fired
/// evidence.
#[test]
fn queued_extension_internal_prompt_submit_request_preserves_ctx_id_when_steered() {
    let td = TempDir::new().expect("tempdir");
    let sp = td.path().join("state");
    let mut h = echo_harness(&sp).expect("harness");
    connect_ready_configured_extension(
        &mut h,
        "utils-ext",
        "utils-ext",
        tau_proto::ClientKind::Tool,
    );
    h.selected_model = Some("test/model".into());
    let cid = ensure_test_user_agent(&mut h);
    let agent_id = durable_agent_id_for_conversation(&h, &cid);
    h.set_agent_turn_state(
        &cid,
        AgentTurnState::AgentThinking {
            agent_prompt_id: test_agent_prompt_id("busy-prompt"),
        },
    );
    h.handle_extension_event(
        "utils-ext",
        TestProtocolItem::Event(Event::ExtInternalPromptSubmitRequest(
            tau_proto::ExtInternalPromptSubmitRequest {
                agent_id: agent_id.clone(),
                text: "timer fired".to_owned(),
                ctx_id: Some("timer:wake:1".to_owned()),
                activation_kind: None,
            },
        )),
    )
    .expect("queue internal prompt request");
    h.fold_pending_prompts_as_steered(&cid);

    assert!(event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::AgentPromptSteered(steered)
            if steered.agent_id == agent_id
                && steered.text == "timer fired"
                && steered.message_class == tau_proto::PromptMessageClass::Internal
                && steered.submission_source
                    == tau_proto::PromptSubmissionSource::Extension {
                        name: tau_proto::ExtensionName::parse("utils-ext")
                            .expect("configured extension name"),
                    }
                && steered.ctx_id.as_deref() == Some("timer:wake:1")
    )));

    h.shutdown().expect("shutdown");
}

/// Queued extension internal-prompt requests must keep their own ctx_id values;
/// a single per-agent scratch slot would make later queued prompts overwrite
/// earlier request correlation ids.
#[test]
fn queued_extension_internal_prompt_submit_requests_preserve_individual_ctx_ids() {
    let td = TempDir::new().expect("tempdir");
    let sp = td.path().join("state");
    let mut h = echo_harness(&sp).expect("harness");
    connect_ready_configured_extension(
        &mut h,
        "utils-ext",
        "utils-ext",
        tau_proto::ClientKind::Tool,
    );
    let cid = ensure_test_user_agent(&mut h);
    let agent_id = durable_agent_id_for_conversation(&h, &cid);
    h.set_agent_turn_state(
        &cid,
        AgentTurnState::AgentThinking {
            agent_prompt_id: test_agent_prompt_id("busy-prompt"),
        },
    );

    for (text, ctx_id) in [("first", "ctx-1"), ("second", "ctx-2")] {
        h.handle_extension_event(
            "utils-ext",
            TestProtocolItem::Event(Event::ExtInternalPromptSubmitRequest(
                tau_proto::ExtInternalPromptSubmitRequest {
                    agent_id: agent_id.clone(),
                    text: text.to_owned(),
                    ctx_id: Some(ctx_id.to_owned()),
                    activation_kind: None,
                },
            )),
        )
        .expect("queue prompt request");
    }

    let queued_ctx_ids: Vec<_> = h.agents[&cid]
        .pending_prompts
        .iter()
        .map(|prompt| prompt.ctx_id.as_deref())
        .collect();
    assert_eq!(queued_ctx_ids, vec![Some("ctx-1"), Some("ctx-2")]);

    h.set_agent_turn_state(&cid, AgentTurnState::Idle);
    h.try_advance_queue();
    assert!(event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::AgentPromptCreated(created)
            if created.agent_id == agent_id && created.ctx_id.as_deref() == Some("ctx-1")
    )));

    let first = read_nth_prompt_created(&h, 0);
    h.handle_provider_response_finished(provider_text_response(
        &first.agent_prompt_id,
        first.agent_id,
        "first done",
    ))
    .expect("durably finish first checkpointed dispatch");
    h.try_advance_queue();
    assert!(event_log_contains_any_source(&h, |event| matches!(
        event,
        Event::AgentPromptCreated(created)
            if created.agent_id == agent_id && created.ctx_id.as_deref() == Some("ctx-2")
    )));

    h.shutdown().expect("shutdown");
}

#[test]
fn agent_metadata_validation_rejects_bad_key_size_value_and_unknown_target() {
    let td = TempDir::new().expect("tempdir");
    let sp = td.path().join("state");
    let mut h = echo_harness(&sp).expect("start");
    let agent_id = tau_proto::AgentId::parse("metadata-target").expect("agent id");
    h.session_loaded_agents.insert(agent_id.clone());

    let valid = tau_proto::AgentMetadataSet {
        agent_id: agent_id.clone(),
        key: tau_proto::AgentMetadataKey::new("ok"),
        value: CborValue::Text("value".to_owned()),
        mutation_id: None,
        inheritable: false,
    };
    h.validate_agent_metadata_set(&valid)
        .expect("valid metadata set");

    let empty_key = tau_proto::AgentMetadataSet {
        key: tau_proto::AgentMetadataKey::new(""),
        ..valid.clone()
    };
    assert!(
        h.validate_agent_metadata_set(&empty_key)
            .expect_err("empty key rejected")
            .contains("must not be empty")
    );

    let oversized_key = tau_proto::AgentMetadataSet {
        key: tau_proto::AgentMetadataKey::new(
            "k".repeat(tau_proto::MAX_AGENT_METADATA_KEY_BYTES + 1),
        ),
        ..valid.clone()
    };
    assert!(
        h.validate_agent_metadata_set(&oversized_key)
            .expect_err("oversized key rejected")
            .contains("exceeds 256 bytes")
    );

    let oversized_value = tau_proto::AgentMetadataSet {
        value: CborValue::Bytes(vec![0; tau_proto::MAX_AGENT_METADATA_VALUE_BYTES + 1]),
        ..valid.clone()
    };
    assert!(
        h.validate_agent_metadata_set(&oversized_value)
            .expect_err("oversized value rejected")
            .contains("exceeds 64 KiB")
    );

    let unknown = tau_proto::AgentMetadataSet {
        agent_id: tau_proto::AgentId::parse("unknown-agent").expect("agent id"),
        ..valid
    };
    assert!(
        h.validate_agent_metadata_set(&unknown)
            .expect_err("unknown target rejected")
            .contains("unknown agent metadata target")
    );

    let reserved_key = tau_proto::AgentMetadataKey::new(
        path_crate_harness::subagents_tool::PEER_ENTRYPOINT_AGENT_METADATA_KEY,
    );
    let reserved_set = tau_proto::AgentMetadataSet {
        agent_id: agent_id.clone(),
        key: reserved_key.clone(),
        value: CborValue::Bool(false),
        mutation_id: None,
        inheritable: false,
    };
    assert!(
        h.validate_agent_metadata_set(&reserved_set)
            .expect_err("reserved set rejected")
            .contains("reserved")
    );
    assert!(
        h.validate_agent_metadata_unset(&tau_proto::AgentMetadataUnset {
            agent_id: agent_id.clone(),
            key: reserved_key.clone(),
        })
        .expect_err("reserved unset rejected")
        .contains("reserved")
    );
    assert!(
        h.validate_initial_agent_metadata(&[tau_proto::AgentInitialMetadata {
            key: reserved_key,
            value: CborValue::Bool(true),
            inheritable: false,
        }])
        .expect_err("reserved initial metadata rejected")
        .contains("reserved")
    );

    h.shutdown().expect("shutdown");
}

/// An explicit-parent typed start inherits only eligible metadata, then returns
/// exactly one result and detaches into a loaded ordinary worker. A fresh user
/// turn must preserve membership without reviving the completed request.
#[test]
fn explicit_parent_typed_start_inherits_metadata_and_remains_loaded_after_completion() {
    let td = TempDir::new().expect("tempdir");
    let sp = td.path().join("state");
    let mut h = echo_harness(&sp).expect("start");
    h.selected_model = Some("test/model".into());
    let result_frames = connect_test_tool(&mut h, "conn-delegate");
    h.submit_user_prompt(test_session_id("s1"), "parent prompt".to_owned())
        .expect("submit parent");
    let parent_agent_id = h
        .agents
        .get(&test_user_agent(&h))
        .and_then(|conversation| conversation.agent_id.clone())
        .expect("parent agent id");
    let parent = tau_proto::AgentId::parse(&parent_agent_id).expect("parent agent id");
    let inherit_key = tau_proto::AgentMetadataKey::new("inherit-key");
    let local_key = tau_proto::AgentMetadataKey::new("local-key");

    for (key, value, inheritable) in [
        (inherit_key.clone(), "inherited", true),
        (local_key, "local", false),
    ] {
        h.publish_event(
            None,
            Event::AgentMetadataSet(tau_proto::AgentMetadataSet {
                agent_id: parent.clone(),
                key,
                value: CborValue::Text(value.to_owned()),
                mutation_id: None,
                inheritable,
            }),
        );
    }

    h.handle_start_agent_request(
        &crate::test_connection_id("conn-delegate"),
        StartAgentRequest {
            trusted_internal_spans: Vec::new(),
            parent_agent: Some(parent.clone()),
            query_id: "q-inherit".to_owned(),
            instruction: "side task".to_owned(),
            role: None,
            input_stats: tau_proto::ToolUseStats::default(),
            tool_call_id: None,
            task_name: None,
        },
    )
    .expect("start child");
    let child_cid = ext_query_cid(&h, "q-inherit").expect("child conversation");
    let child_agent_id = durable_agent_id_for_conversation(&h, &child_cid);

    let child_events = h
        .agent_store
        .agent_events(child_agent_id.as_str())
        .expect("child events");
    assert!(child_events.iter().any(|entry| matches!(
        &entry.event,
        Event::AgentMetadataSet(set)
            if set.agent_id == child_agent_id
                && set.key == inherit_key
                && set.value == CborValue::Text("inherited".to_owned())
                && set.inheritable
    )));
    assert!(child_events.iter().all(|entry| !matches!(
        &entry.event,
        Event::AgentMetadataSet(set) if set.key.as_str() == "local-key"
    )));

    let child_prompt_id = h
        .prompt_agents
        .iter()
        .find_map(|(prompt_id, cid)| (cid == &child_cid).then_some(prompt_id.clone()))
        .expect("child prompt");
    let mut response =
        provider_text_response(&child_prompt_id, child_agent_id.clone(), "side result");
    response.originator = tau_proto::PromptOriginator::Extension {
        name: crate::test_extension_name("conn-delegate"),
        query_id: "q-inherit".to_owned(),
    };
    h.handle_provider_response_finished(response)
        .expect("complete explicit-parent child");

    let child = h.agents.get(&child_cid).expect("completed child retained");
    assert!(child.originator.is_user());
    assert!(child.source_connection.is_none());
    assert!(child.parent_tool_call_id.is_none());
    assert!(child.parent_agent_id.is_none());
    assert_eq!(
        h.agent_navigation_modes.get(&child_agent_id),
        Some(&tau_proto::AgentNavigationMode::ActiveAuto)
    );
    assert_eq!(
        result_frames
            .lock()
            .expect("result frames")
            .iter()
            .filter(|frame| matches!(
                peel_inner_event(&frame.frame),
                Some(Event::StartAgentResult(result)) if result.query_id == "q-inherit"
            ))
            .count(),
        1
    );

    h.handle_authenticated_ui_prompt_submitted(UiPromptSubmitted {
        literal: false,
        session_id: test_session_id("s1"),
        text: "fresh child turn".to_owned(),
        agent_id: child_agent_id.clone(),
        message_class: tau_proto::PromptMessageClass::User,
        originator: tau_proto::PromptOriginator::User,
        ctx_id: None,
    })
    .expect("submit fresh child turn");
    let fresh_prompt_id = h
        .agents
        .get(&child_cid)
        .and_then(|child| child.in_flight_prompt.clone())
        .expect("fresh child prompt");
    h.handle_provider_response_finished(provider_text_response(
        &fresh_prompt_id,
        child_agent_id.clone(),
        "fresh result",
    ))
    .expect("complete fresh child turn");

    assert!(h.agents.contains_key(&child_cid));
    assert!(h.session_loaded_agents.contains(&child_agent_id));
    assert_eq!(
        result_frames
            .lock()
            .expect("result frames")
            .iter()
            .filter(|frame| matches!(
                peel_inner_event(&frame.frame),
                Some(Event::StartAgentResult(result)) if result.query_id == "q-inherit"
            ))
            .count(),
        1,
        "a fresh user turn must not complete the old start request again"
    );
    let session_events = h.store.session_events("s1").expect("session events");
    assert_eq!(
        session_events
            .iter()
            .filter(|record| matches!(
                &record.event,
                Event::SessionAgentLoaded(loaded)
                    if loaded.agent_id == child_agent_id
            ))
            .count(),
        1
    );
    assert!(session_events.iter().all(|record| !matches!(
        &record.event,
        Event::SessionAgentUnloaded(unloaded)
            if unloaded.agent_id == child_agent_id
    )));

    h.shutdown().expect("shutdown");
}

/// Ensures full prompt rendering with AGENTS disabled returns only the system
/// wrapper and never falls back to harness-side filesystem discovery.
#[test]
fn rendered_prompt_without_agents_md_uses_system_wrapper_only() {
    let td = TempDir::new().expect("tempdir");
    let mut h = echo_harness(td.path().join("state")).expect("start");
    seed_render_prompt_role(&mut h);

    let result = request_rendered_prompt(&mut h, "debug-role", false);
    let prompt = result.prompt.expect("rendered prompt");

    assert_eq!(result.error, None);
    assert!(prompt.contains("<message role=\"system\">"));
    assert!(prompt.contains("DEBUG ROLE PROMPT"));
    assert!(prompt.contains("Your agent id is `dev-preview-agent`."));
    assert!(!prompt.contains("source=\"AGENTS.md\""));
    assert!(!prompt.contains("AGENTS_FILE"));
    assert!(!prompt.contains("# agents.md files"));
}

/// Ensures full prompt rendering uses only harness-owned discovered AGENTS.md
/// state when AGENTS inclusion is enabled.
#[test]
fn rendered_prompt_with_seeded_agents_md_includes_synthetic_agents_message() {
    let td = TempDir::new().expect("tempdir");
    let mut h = echo_harness(td.path().join("state")).expect("start");
    seed_render_prompt_role(&mut h);
    h.discovered_agents_files.push(DiscoveredAgentsFile {
        source_id: crate::test_connection_id("shell"),
        file_path: td.path().join("AGENTS.md"),
        content: "seeded AGENTS instructions\n".to_owned(),
    });

    let result = request_rendered_prompt(&mut h, "debug-role", true);
    let prompt = result.prompt.expect("rendered prompt");

    assert_eq!(result.error, None);
    assert!(prompt.contains("<message role=\"user\" synthetic=\"true\" source=\"AGENTS.md\">"));
    assert_eq!(
        prompt
            .lines()
            .filter(|line| *line == "# agents.md files")
            .count(),
        1
    );
    assert!(prompt.contains("# agents.md files\n\n<AGENTS_FILE"));
    assert!(prompt.contains("<AGENTS_FILE path="));
    assert!(prompt.contains("seeded AGENTS instructions"));
}

/// Ensures full prompt rendering reports unknown roles in-band on the request
/// path instead of synthesizing a prompt.
#[test]
fn rendered_prompt_unknown_role_returns_in_band_error() {
    let td = TempDir::new().expect("tempdir");
    let mut h = echo_harness(td.path().join("state")).expect("start");
    seed_render_prompt_role(&mut h);

    let result = request_rendered_prompt(&mut h, "missing-role", true);

    assert_eq!(result.prompt, None);
    assert_eq!(result.error, Some("unknown role: missing-role".to_owned()));
}

fn seed_render_prompt_role(h: &mut Harness) {
    h.available_roles = path_std_collections::HashMap::from([(
        "debug-role".to_owned(),
        tau_config::settings::AgentRole {
            prompt_fragments: vec![tau_config::settings::RolePromptFragment {
                name: "debug.instructions".to_owned(),
                priority: tau_proto::PromptPriority::new(100),
                text: tau_proto::PromptContent::new("DEBUG ROLE PROMPT"),
            }],
            ..Default::default()
        },
    )]);
}

fn request_rendered_prompt(
    h: &mut Harness,
    role: &str,
    enable_agents_md: bool,
) -> tau_proto::RenderedPromptResult {
    let frames = connect_test_client(h, "render-prompt-test", tau_proto::ClientKind::Ui);
    h.send_rendered_prompt_result(
        &crate::test_connection_id("render-prompt-test"),
        tau_proto::GetRenderedPrompt {
            request_id: "request-1".to_owned(),
            role: Some(role.to_owned()),
            enable_agents_md,
        },
    );
    let frames = frames.lock().expect("frames lock");
    frames
        .iter()
        .find_map(|frame| match &frame.frame {
            HarnessOutputMessage::RenderedPromptResult(result) => Some((**result).clone()),
            _ => None,
        })
        .expect("rendered prompt result")
}

/// Cancelling a disconnected preview requester must discard its waiting
/// ephemeral agent so a context provider that never becomes ready cannot leak
/// runtime routes or deferred response state.
#[test]
fn disconnect_cancels_pending_rendered_preview() {
    let td = TempDir::new().expect("tempdir");
    let mut h = quiet_provider_harness(td.path().join("state")).expect("start");
    let requester = crate::test_connection_id("preview-disconnect-requester");
    let _frames = connect_test_client(&mut h, requester.as_str(), tau_proto::ClientKind::Ui);
    let cid = h.create_durable_user_agent(h.current_session_id.clone(), &h.selected_role.clone());
    let agent_id = durable_agent_id_for_conversation(&h, &cid);
    h.pending_rendered_prompts.insert(
        agent_id.clone(),
        vec![PendingRenderedPrompt::Prompt {
            connection_id: requester.clone(),
            request_id: "preview-disconnect".to_owned(),
            role: h.selected_role.clone(),
            enable_agents_md: false,
        }],
    );

    h.handle_disconnect_at(&requester, Instant::now());

    assert!(!h.pending_rendered_prompts.contains_key(&agent_id));
    assert!(
        h.runtime_agent_id_for_target_agent(Some(agent_id.as_str()))
            .is_none()
    );
}

/// Replacing a session must cancel previews that are still waiting for
/// extension context, rather than retaining an unanswerable response entry.
#[test]
fn session_switch_cancels_pending_rendered_preview() {
    let td = TempDir::new().expect("tempdir");
    let mut h = quiet_provider_harness(td.path().join("state")).expect("start");
    let cid = h.create_durable_user_agent(h.current_session_id.clone(), &h.selected_role.clone());
    let agent_id = durable_agent_id_for_conversation(&h, &cid);
    h.pending_rendered_prompts.insert(
        agent_id.clone(),
        vec![PendingRenderedPrompt::System {
            connection_id: crate::test_connection_id("preview-switch-requester"),
            request_id: "preview-switch".to_owned(),
            role: h.selected_role.clone(),
        }],
    );

    h.switch_session(
        "preview-replacement".parse().expect("session id"),
        tau_proto::SessionStartReason::New,
    )
    .expect("switch session");

    assert!(!h.pending_rendered_prompts.contains_key(&agent_id));
    assert!(
        h.runtime_agent_id_for_target_agent(Some(agent_id.as_str()))
            .is_none()
    );
}

#[test]
fn ui_emitted_custom_event_routes_to_subscribed_extension() {
    // A UI client drives a stateful extension (the task factory's
    // request/snapshot exchange) by emitting an extension-owned custom event.
    // It must reach an extension that subscribed to that event name, the same
    // way an extension-emitted custom event reaches the UI.
    let td = TempDir::new().expect("tempdir");
    let sp = td.path().join("state");
    let mut h = quiet_provider_harness(&sp).expect("start");

    let ext = connect_test_client(&mut h, "factory-ext", tau_proto::ClientKind::Tool);
    let command_name: tau_proto::EventName = "factory.sync".parse().expect("event name");
    h.bus
        .set_subscriptions(
            &crate::test_connection_id("factory-ext"),
            Vec::new(),
            vec![EventSelector::Prefix("factory.".to_owned())],
        )
        .expect("extension subscription");
    let _ui = connect_test_client_with_origin(
        &mut h,
        "ui",
        tau_proto::ClientKind::Ui,
        ConnectionOrigin::Socket,
    );

    h.handle_client_event_inner(
        &crate::test_connection_id("ui"),
        Event::ExtensionEvent(
            tau_proto::CustomEvent::try_new(command_name.clone(), None, CborValue::Null)
                .expect("valid custom event"),
        ),
    )
    .expect("ui custom event handled");

    let frames = ext.lock().expect("extension sink");
    assert!(frames.iter().any(|routed| matches!(
        peel_inner_event(&routed.frame),
        Some(Event::ExtensionEvent(custom)) if *custom.name() == command_name
    )));
}

#[test]
fn ui_cannot_emit_custom_event_with_reserved_first_party_category() {
    // The reserved-category guard lives in `CustomEvent::try_new`, which the
    // deserialize path re-runs — so a UI cannot construct a custom event named
    // under `harness`/`agent`/`tool`/`extension` to spoof a first-party fact.
    let reserved: tau_proto::EventName = "harness.notice".parse().expect("event name");
    assert!(
        tau_proto::CustomEvent::try_new(reserved, None, CborValue::Null).is_err(),
        "reserved first-party category must be rejected at construction"
    );
}
/// An embedded tool round retains provider-requested arguments and observed
/// terminal metadata while stripping directed image bytes from the trace.
#[test]
fn embedded_tool_trace_records_call_and_byte_free_result() {
    let call = ToolCallItem {
        call_id: "call-image".into(),
        name: ToolName::new("read_image"),
        tool_type: tau_proto::ToolType::Function,
        arguments: CborValue::Map(vec![(
            CborValue::Text("mode".to_owned()),
            CborValue::Text("overview".to_owned()),
        )]),
        raw_arguments_json: None,
        responses_envelope: None,
    };
    let mut calls = Vec::new();
    super::super::record_embedded_tool_calls(&[ContextItem::ToolCall(call.clone())], &mut calls);
    assert_eq!(calls, vec![call]);

    let result = ToolResult {
        presentation: Default::default(),
        call_id: "call-image".into(),
        tool_name: ToolName::new("read_image"),
        tool_type: tau_proto::ToolType::Function,
        result: CborValue::Map(vec![(
            CborValue::Text("mode".to_owned()),
            CborValue::Text("overview".to_owned()),
        )]),
        provider_content: vec![tau_proto::ToolResultContentPart::Image(
            tau_proto::ImageContent {
                media_type: tau_proto::ImageMediaType::Png,
                data: vec![1, 2, 3].into(),
                width: 1,
                height: 1,
                detail: tau_proto::ImageDetail::High,
            },
        )],
        kind: tau_proto::ToolResultKind::Final,
        display: None,
        originator: tau_proto::PromptOriginator::User,
    };
    let observed = super::super::byte_free_embedded_tool_result(&result);
    assert_eq!(observed.result, result.result);
    assert!(observed.provider_content.is_empty());
}

/// Ensures all three UI actions are absolute shared writes while stale-session
/// and extension-originated requests cannot mutate the loaded agent's mode.
#[test]
fn shared_agent_navigation_mode_writes_are_ui_only_and_absolute() {
    let td = TempDir::new().expect("tempdir");
    let mut h = echo_harness(td.path().join("state")).expect("harness");
    let requester = connect_test_client(&mut h, "navigation-ui", tau_proto::ClientKind::Ui);
    let observer = connect_test_client(&mut h, "navigation-observer", tau_proto::ClientKind::Ui);
    let external = connect_test_client(
        &mut h,
        "navigation-external",
        tau_proto::ClientKind::External,
    );
    let promoted_external =
        connect_test_client(&mut h, "navigation-promoted", tau_proto::ClientKind::Ui);
    let promoted_external_id = h
        .bus
        .connections()
        .into_iter()
        .find(|connection| connection.name == "navigation-promoted")
        .expect("promoted external connection")
        .id;
    h.external_message_peers
        .insert(promoted_external_id.clone());
    h.submit_user_prompt(h.current_session_id.clone(), "hello".to_owned())
        .expect("create user agent");
    let agent_id = h
        .session_loaded_agents
        .iter()
        .next()
        .cloned()
        .expect("loaded agent");
    h.bus
        .set_subscriptions(
            &crate::test_connection_id("navigation-observer"),
            Vec::new(),
            vec![EventSelector::Exact(
                tau_proto::EventName::AGENT_STATS_UPDATED,
            )],
        )
        .expect("observer subscription");
    requester.lock().expect("requester frames").clear();
    observer.lock().expect("observer frames").clear();
    assert_eq!(
        h.agent_navigation_modes.get(&agent_id),
        Some(&tau_proto::AgentNavigationMode::Active)
    );

    for (index, action, expected) in [
        (
            1,
            tau_proto::UiAgentNavigationModeAction::SetSuspended,
            tau_proto::AgentNavigationMode::Suspended,
        ),
        (
            2,
            tau_proto::UiAgentNavigationModeAction::SetActiveAuto,
            tau_proto::AgentNavigationMode::ActiveAuto,
        ),
        (
            3,
            tau_proto::UiAgentNavigationModeAction::SetActive,
            tau_proto::AgentNavigationMode::Active,
        ),
    ] {
        h.handle_client_event_inner(
            &crate::test_connection_id("navigation-ui"),
            Event::UiSetAgentNavigationMode(tau_proto::UiSetAgentNavigationMode {
                request_id: format!("navigation-{index}"),
                session_id: h.current_session_id.clone(),
                agent_id: agent_id.clone(),
                action,
            }),
        )
        .expect("UI navigation request");
        assert_eq!(h.agent_navigation_modes.get(&agent_id), Some(&expected));
    }

    h.handle_client_event_inner(
        &crate::test_connection_id("navigation-ui"),
        Event::UiSetAgentNavigationMode(tau_proto::UiSetAgentNavigationMode {
            request_id: "stale".to_owned(),
            session_id: test_session_id("other-session"),
            agent_id: agent_id.clone(),
            action: tau_proto::UiAgentNavigationModeAction::SetSuspended,
        }),
    )
    .expect("stale UI request");
    assert_eq!(
        h.agent_navigation_modes.get(&agent_id),
        Some(&tau_proto::AgentNavigationMode::Active)
    );

    h.handle_client_event_inner(
        &crate::test_connection_id("navigation-ui"),
        Event::UiSetAgentNavigationMode(tau_proto::UiSetAgentNavigationMode {
            request_id: "unloaded".to_owned(),
            session_id: h.current_session_id.clone(),
            agent_id: tau_proto::AgentId::parse("unknown-agent").expect("agent id"),
            action: tau_proto::UiAgentNavigationModeAction::SetSuspended,
        }),
    )
    .expect("unloaded request");

    h.handle_client_event_inner(
        &crate::test_connection_id("navigation-external"),
        Event::UiSetAgentNavigationMode(tau_proto::UiSetAgentNavigationMode {
            request_id: "external".to_owned(),
            session_id: h.current_session_id.clone(),
            agent_id: agent_id.clone(),
            action: tau_proto::UiAgentNavigationModeAction::SetSuspended,
        }),
    )
    .expect("external request consumed");
    assert_eq!(
        h.agent_navigation_modes.get(&agent_id),
        Some(&tau_proto::AgentNavigationMode::Active)
    );
    assert!(external.lock().expect("external frames").is_empty());
    h.handle_client_event_inner(
        &promoted_external_id,
        Event::UiSetAgentNavigationMode(tau_proto::UiSetAgentNavigationMode {
            request_id: "promoted-external".to_owned(),
            session_id: h.current_session_id.clone(),
            agent_id: agent_id.clone(),
            action: tau_proto::UiAgentNavigationModeAction::SetSuspended,
        }),
    )
    .expect("promoted external request consumed");
    assert_eq!(
        h.agent_navigation_modes.get(&agent_id),
        Some(&tau_proto::AgentNavigationMode::Active)
    );
    assert!(
        promoted_external
            .lock()
            .expect("promoted external frames")
            .is_empty()
    );
    let results = requester
        .lock()
        .expect("requester frames")
        .iter()
        .filter_map(|frame| match peel_inner_event(&frame.frame) {
            Some(Event::UiSetAgentNavigationModeResult(result)) => Some(result.clone()),
            _ => None,
        })
        .collect::<Vec<_>>();
    assert_eq!(results.len(), 5);
    assert_eq!(
        results
            .iter()
            .map(|result| (result.request_id.as_str(), result.outcome))
            .collect::<Vec<_>>(),
        vec![
            (
                "navigation-1",
                tau_proto::UiSetAgentNavigationModeOutcome::Applied,
            ),
            (
                "navigation-2",
                tau_proto::UiSetAgentNavigationModeOutcome::Applied,
            ),
            (
                "navigation-3",
                tau_proto::UiSetAgentNavigationModeOutcome::Applied,
            ),
            (
                "stale",
                tau_proto::UiSetAgentNavigationModeOutcome::Rejected {
                    reason: tau_proto::UiSetAgentNavigationModeRejection::StaleSession,
                },
            ),
            (
                "unloaded",
                tau_proto::UiSetAgentNavigationModeOutcome::Rejected {
                    reason: tau_proto::UiSetAgentNavigationModeRejection::AgentNotLoaded,
                },
            ),
        ]
    );
    assert!(
        !observer
            .lock()
            .expect("observer frames")
            .iter()
            .any(|frame| {
                matches!(
                    peel_inner_event(&frame.frame),
                    Some(Event::UiSetAgentNavigationModeResult(_))
                )
            })
    );
    let observed_modes = observer
        .lock()
        .expect("observer frames")
        .iter()
        .filter_map(|frame| match peel_inner_event(&frame.frame) {
            Some(Event::AgentStatsUpdated(stats)) if stats.agent_id == agent_id => {
                Some(stats.navigation_mode)
            }
            _ => None,
        })
        .collect::<Vec<_>>();
    assert_eq!(
        observed_modes,
        vec![
            tau_proto::AgentNavigationMode::Suspended,
            tau_proto::AgentNavigationMode::ActiveAuto,
            tau_proto::AgentNavigationMode::Active,
        ]
    );
    h.handle_client_event_inner(
        &crate::test_connection_id("navigation-ui"),
        Event::UiSetAgentNavigationMode(tau_proto::UiSetAgentNavigationMode {
            request_id: "before-reconnect".to_owned(),
            session_id: h.current_session_id.clone(),
            agent_id: agent_id.clone(),
            action: tau_proto::UiAgentNavigationModeAction::SetSuspended,
        }),
    )
    .expect("set mode before reconnect");
    h.handle_authenticated_ui_prompt_submitted(UiPromptSubmitted {
        literal: false,
        session_id: h.current_session_id.clone(),
        text: "resume before reconnect".to_owned(),
        agent_id: agent_id.clone(),
        message_class: tau_proto::PromptMessageClass::User,
        originator: tau_proto::PromptOriginator::User,
        ctx_id: Some("navigation-reconnect".to_owned()),
    })
    .expect("accepted prompt before reconnect");
    assert_eq!(
        h.agent_navigation_modes.get(&agent_id),
        Some(&tau_proto::AgentNavigationMode::Active)
    );
    h.bus
        .disconnect(&crate::test_connection_id("navigation-ui"));
    let reconnected =
        connect_test_client(&mut h, "navigation-reconnected", tau_proto::ClientKind::Ui);
    h.complete_subscription(
        &crate::test_connection_id("navigation-reconnected"),
        vec![EventSelector::Exact(
            tau_proto::EventName::AGENT_STATS_UPDATED,
        )],
        vec![EventSelector::Exact(
            tau_proto::EventName::AGENT_STATS_UPDATED,
        )],
    )
    .expect("reconnected catch-up");
    assert!(
        reconnected
            .lock()
            .expect("reconnected frames")
            .iter()
            .any(|frame| matches!(
                peel_inner_event(&frame.frame),
                Some(Event::AgentStatsUpdated(stats))
                    if stats.agent_id == agent_id
                        && stats.navigation_mode == tau_proto::AgentNavigationMode::Active
            ))
    );

    let extension_event = Event::UiSetAgentNavigationMode(tau_proto::UiSetAgentNavigationMode {
        request_id: "extension".to_owned(),
        session_id: h.current_session_id.clone(),
        agent_id: agent_id.clone(),
        action: tau_proto::UiAgentNavigationModeAction::SetSuspended,
    });
    connect_test_tool(&mut h, "extension-test");
    h.handle_extension_event_inner(
        &crate::test_connection_id("extension-test"),
        extension_event,
    )
    .expect("extension intake");
    assert_eq!(
        h.agent_navigation_modes.get(&agent_id),
        Some(&tau_proto::AgentNavigationMode::Active)
    );
    h.react_to_committed_event(
        None,
        &Event::SessionAgentUnloaded(tau_proto::SessionAgentUnloaded {
            session_id: h.current_session_id.clone(),
            agent_id: agent_id.clone(),
        }),
        true,
        None,
    );
    assert!(!h.agent_navigation_modes.contains_key(&agent_id));
    h.agent_navigation_modes
        .insert(agent_id.clone(), tau_proto::AgentNavigationMode::Suspended);
    h.switch_session(
        test_session_id("navigation-next"),
        tau_proto::SessionStartReason::New,
    )
    .expect("switch session");
    assert!(h.agent_navigation_modes.is_empty());
    h.shutdown().expect("shutdown");
}

/// Ensures create admission returns exactly one correlated point-to-point
/// rejection and never exposes that transient result to another UI.
#[test]
fn ui_create_agent_rejection_is_correlated_and_point_to_point() {
    let td = TempDir::new().expect("tempdir");
    let mut h = echo_harness(td.path().join("state")).expect("harness");
    let requester = connect_test_client(&mut h, "create-requester", tau_proto::ClientKind::Ui);
    let observer = connect_test_client(&mut h, "create-observer", tau_proto::ClientKind::Ui);

    h.handle_ui_create_agent_from(
        &crate::test_connection_id("create-requester"),
        tau_proto::UiCreateAgent {
            request_id: "create-missing-role".to_owned(),
            session_id: h.current_session_id.clone(),
            role: "missing-role".to_owned(),
            model_override: None,
            metadata: Vec::new(),
            initial_prompt: Some("never admitted".to_owned()),
            literal: false,
            message_class: tau_proto::PromptMessageClass::User,
            originator: tau_proto::PromptOriginator::User,
            ctx_id: Some("create-missing-role-prompt".to_owned()),
            parent_agent: None,
            ephemeral: false,
        },
    )
    .expect("create rejection");

    let results = requester
        .lock()
        .expect("requester frames")
        .iter()
        .filter_map(|frame| match peel_inner_event(&frame.frame) {
            Some(Event::UiCreateAgentResult(result)) => Some(result.clone()),
            _ => None,
        })
        .collect::<Vec<_>>();
    assert_eq!(results.len(), 1);
    assert_eq!(results[0].request_id, "create-missing-role");
    assert!(matches!(
        results[0].outcome,
        tau_proto::UiCreateAgentOutcome::Rejected {
            reason: tau_proto::UiCreateAgentRejection::RoleUnavailable,
            agent_id: None,
            ..
        }
    ));
    assert!(
        observer
            .lock()
            .expect("observer frames")
            .iter()
            .all(|frame| !matches!(
                peel_inner_event(&frame.frame),
                Some(Event::UiCreateAgentResult(_))
            ))
    );
    assert!(h.session_loaded_agents.is_empty());
}

/// Admission rejects malformed request and prompt correlations before creating
/// an agent, while a promptless request succeeds without a prompt correlation.
#[test]
fn ui_create_agent_validates_correlations_and_accepts_promptless_creation() {
    let td = TempDir::new().expect("tempdir");
    let mut h = echo_harness(td.path().join("state")).expect("harness");
    let requester = connect_test_client(&mut h, "correlation-ui", tau_proto::ClientKind::Ui);
    let session_id = h.current_session_id.clone();
    for (request_id, ctx_id) in [
        ("", Some("prompt-correlation")),
        ("missing-prompt-correlation", None),
    ] {
        h.handle_ui_create_agent_from(
            &crate::test_connection_id("correlation-ui"),
            tau_proto::UiCreateAgent {
                request_id: request_id.to_owned(),
                session_id: session_id.clone(),
                role: "engineer".to_owned(),
                model_override: None,
                metadata: Vec::new(),
                initial_prompt: Some("hello".to_owned()),
                literal: false,
                message_class: tau_proto::PromptMessageClass::User,
                originator: tau_proto::PromptOriginator::User,
                ctx_id: ctx_id.map(str::to_owned),
                parent_agent: None,
                ephemeral: false,
            },
        )
        .expect("reject malformed correlation");
    }
    assert!(h.session_loaded_agents.is_empty());

    for (request_id, request_session, metadata, parent_agent) in [
        (
            "stale-session",
            test_session_id("stale-session"),
            Vec::new(),
            None,
        ),
        (
            "invalid-metadata",
            session_id.clone(),
            vec![tau_proto::AgentInitialMetadata {
                key: tau_proto::AgentMetadataKey::new("oversized"),
                value: tau_proto::CborValue::Bytes(vec![
                    0;
                    tau_proto::MAX_AGENT_METADATA_VALUE_BYTES
                        + 1
                ]),
                inheritable: false,
            }],
            None,
        ),
        (
            "missing-parent",
            session_id.clone(),
            Vec::new(),
            Some(tau_proto::AgentId::parse("missing-parent").expect("agent id")),
        ),
    ] {
        h.handle_ui_create_agent_from(
            &crate::test_connection_id("correlation-ui"),
            tau_proto::UiCreateAgent {
                request_id: request_id.to_owned(),
                session_id: request_session,
                role: "engineer".to_owned(),
                model_override: None,
                metadata,
                initial_prompt: None,
                literal: false,
                message_class: tau_proto::PromptMessageClass::User,
                originator: tau_proto::PromptOriginator::User,
                ctx_id: None,
                parent_agent,
                ephemeral: false,
            },
        )
        .expect("reject pre-creation request");
    }
    assert!(h.session_loaded_agents.is_empty());

    h.handle_ui_create_agent_from(
        &crate::test_connection_id("correlation-ui"),
        tau_proto::UiCreateAgent {
            request_id: "promptless-create".to_owned(),
            session_id,
            role: "engineer".to_owned(),
            model_override: None,
            metadata: Vec::new(),
            initial_prompt: None,
            literal: false,
            message_class: tau_proto::PromptMessageClass::User,
            originator: tau_proto::PromptOriginator::User,
            ctx_id: None,
            parent_agent: None,
            ephemeral: false,
        },
    )
    .expect("create promptless agent");
    assert_eq!(h.session_loaded_agents.len(), 1);
    let outcomes = requester
        .lock()
        .expect("requester frames")
        .iter()
        .filter_map(|frame| match peel_inner_event(&frame.frame) {
            Some(Event::UiCreateAgentResult(result)) => Some(result.outcome.clone()),
            _ => None,
        })
        .collect::<Vec<_>>();
    assert_eq!(outcomes.len(), 6);
    assert!(matches!(
        outcomes[0],
        tau_proto::UiCreateAgentOutcome::Rejected {
            reason: tau_proto::UiCreateAgentRejection::InvalidRequestId,
            ..
        }
    ));
    assert!(matches!(
        outcomes[1],
        tau_proto::UiCreateAgentOutcome::Rejected {
            reason: tau_proto::UiCreateAgentRejection::InvalidRequestId,
            ..
        }
    ));
    assert!(matches!(
        outcomes[2],
        tau_proto::UiCreateAgentOutcome::Rejected {
            reason: tau_proto::UiCreateAgentRejection::StaleSession,
            ..
        }
    ));
    assert!(matches!(
        outcomes[3],
        tau_proto::UiCreateAgentOutcome::Rejected {
            reason: tau_proto::UiCreateAgentRejection::InvalidMetadata,
            ..
        }
    ));
    assert!(matches!(
        outcomes[4],
        tau_proto::UiCreateAgentOutcome::Rejected {
            reason: tau_proto::UiCreateAgentRejection::ParentNotLoaded,
            ..
        }
    ));
    assert!(matches!(
        outcomes[5],
        tau_proto::UiCreateAgentOutcome::Created {
            initial_prompt: tau_proto::UiCreateAgentInitialPrompt::Absent,
            ..
        }
    ));
}

/// Ensures preprocessing failure follows successful queued admission as a
/// separately correlated prompt terminal.
#[test]
fn ui_create_agent_skill_rejection_reports_partial_creation() {
    let td = TempDir::new().expect("tempdir");
    let mut h = echo_harness(td.path().join("state")).expect("harness");
    let requester = connect_test_client(&mut h, "skill-requester", tau_proto::ClientKind::Ui);

    h.handle_ui_create_agent_from(
        &crate::test_connection_id("skill-requester"),
        tau_proto::UiCreateAgent {
            request_id: "create-missing-skill".to_owned(),
            session_id: h.current_session_id.clone(),
            role: "engineer".to_owned(),
            model_override: None,
            metadata: Vec::new(),
            initial_prompt: Some(":skill missing-skill".to_owned()),
            literal: false,
            message_class: tau_proto::PromptMessageClass::User,
            originator: tau_proto::PromptOriginator::User,
            ctx_id: Some("create-missing-skill-prompt".to_owned()),
            parent_agent: None,
            ephemeral: false,
        },
    )
    .expect("create with invalid skill");
    h.try_advance_queue();

    let result = requester
        .lock()
        .expect("requester frames")
        .iter()
        .find_map(|frame| match peel_inner_event(&frame.frame) {
            Some(Event::UiCreateAgentResult(result)) => Some(result.clone()),
            _ => None,
        })
        .expect("directed create result");
    let tau_proto::UiCreateAgentOutcome::Created {
        agent_id,
        initial_prompt: tau_proto::UiCreateAgentInitialPrompt::Queued,
    } = result.outcome
    else {
        panic!("expected queued create admission");
    };
    assert!(h.session_loaded_agents.contains(&agent_id));
    assert!(event_log_events(&h).into_iter().any(|event| matches!(
        event,
        Event::AgentPromptFailed(failed)
            if failed.request_id == "create-missing-skill"
                && failed.agent_id == agent_id
                && failed.ctx_id == "create-missing-skill-prompt"
                && failed.stage == tau_proto::AgentPromptFailureStage::Preprocessing
    )));
    assert!(event_log_events(&h).into_iter().all(|event| !matches!(
        event,
        Event::AgentPromptSubmitted(prompt) if prompt.agent_id == agent_id
    )));
    let cid = h.agent_routes[agent_id.as_str()].clone();
    h.dispatch_prompt_for_agent(&cid, PendingPrompt::user("after missing skill".to_owned()))
        .expect("dispatch later no-ctx prompt");
    assert!(event_log_events(&h).iter().all(|event| !matches!(
        event,
        Event::AgentPromptCreated(prompt)
            if prompt.ctx_id.as_deref() == Some("create-missing-skill-prompt")
    )));
    assert!(read_nth_prompt_created(&h, 0).ctx_id.is_none());
}

/// A committed initial submission keeps its correlation until provider-prompt
/// materialization, so session rollover can emit a terminal instead of losing
/// the accepted prompt.
#[test]
fn initial_prompt_correlation_survives_submission_until_rollover_terminal() {
    let td = TempDir::new().expect("tempdir");
    let mut h = echo_harness(td.path().join("state")).expect("harness");
    let cid = ensure_test_user_agent(&mut h);
    let agent_id = durable_agent_id_for_conversation(&h, &cid);
    h.complete_agent_publish(
        &cid,
        AgentPublishCompletion::InitialPromptSubmission {
            correlation: crate::agent::InitialPromptCorrelation {
                request_id: "create-rollover".to_owned(),
                agent_id: agent_id.clone(),
                ctx_id: "prompt-rollover".to_owned(),
                activation_through: None,
            },
        },
        tau_proto::AgentHead::Root,
    );
    assert!(h.pending_initial_prompt_correlations.contains_key(&cid));

    h.switch_session(
        test_session_id("replacement-session"),
        tau_proto::SessionStartReason::New,
    )
    .expect("switch session");
    assert!(event_log_events(&h).iter().any(|event| matches!(
        event,
        Event::AgentPromptFailed(failed)
            if failed.request_id == "create-rollover"
                && failed.agent_id == agent_id
                && failed.ctx_id == "prompt-rollover"
                && failed.stage == tau_proto::AgentPromptFailureStage::LifecycleTeardown
    )));
}

/// A render/materialization error before `AgentPromptCreated` consumes the
/// retained correlation through `agent.prompt_failed`.
#[test]
fn initial_prompt_materialization_error_publishes_precreated_terminal() {
    let td = TempDir::new().expect("tempdir");
    let mut h = echo_harness(td.path().join("state")).expect("harness");
    let cid = ensure_test_user_agent(&mut h);
    let agent_id = durable_agent_id_for_conversation(&h, &cid);
    h.complete_agent_publish(
        &cid,
        AgentPublishCompletion::InitialPromptSubmission {
            correlation: crate::agent::InitialPromptCorrelation {
                request_id: "create-render".to_owned(),
                agent_id: agent_id.clone(),
                ctx_id: "prompt-render".to_owned(),
                activation_through: None,
            },
        },
        tau_proto::AgentHead::Root,
    );
    let prompt_id = tau_proto::AgentPromptId::parse("ap-render-failure").expect("prompt id");
    let mut failure = provider_text_response(&prompt_id, agent_id.clone(), "");
    failure.stop_reason = tau_proto::ProviderStopReason::Error;
    failure.error = Some("render failed".to_owned());
    h.publish_event_for_agent_with_completion(
        &cid,
        None,
        Event::ProviderResponseFinished(failure),
        None,
        false,
    );

    assert!(event_log_events(&h).iter().any(|event| matches!(
        event,
        Event::AgentPromptFailed(failed)
            if failed.request_id == "create-render"
                && failed.agent_id == agent_id
                && failed.ctx_id == "prompt-render"
                && failed.stage == tau_proto::AgentPromptFailureStage::Submission
    )));
}

/// A startup-blocked initial skill prompt must be preprocessed before a
/// message-wake steering drain; missing skills terminate instead of entering
/// the transcript as raw `:skill` text.
#[test]
fn queued_initial_skill_is_resolved_before_steering_drain() {
    let td = TempDir::new().expect("tempdir");
    let mut h = echo_harness(td.path().join("state")).expect("harness");
    h.resolving_initial_extension_collisions = true;
    h.handle_ui_create_agent_from(
        &crate::test_connection_id("ui-create-test"),
        tau_proto::UiCreateAgent {
            request_id: "create-steered-skill".to_owned(),
            session_id: h.current_session_id.clone(),
            role: "engineer".to_owned(),
            model_override: None,
            metadata: Vec::new(),
            initial_prompt: Some(":skill missing-steered-skill".to_owned()),
            literal: false,
            message_class: tau_proto::PromptMessageClass::User,
            originator: tau_proto::PromptOriginator::User,
            ctx_id: Some("prompt-steered-skill".to_owned()),
            parent_agent: None,
            ephemeral: false,
        },
    )
    .expect("queue initial prompt");
    let cid = test_user_agent(&h);
    assert!(!h.fold_pending_prompts_as_steered_with_completion(&cid, None));

    assert!(event_log_events(&h).iter().any(|event| matches!(
        event,
        Event::AgentPromptFailed(failed)
            if failed.request_id == "create-steered-skill"
                && failed.ctx_id == "prompt-steered-skill"
                && failed.stage == tau_proto::AgentPromptFailureStage::Preprocessing
    )));
    assert!(event_log_events(&h).iter().all(|event| !matches!(
        event,
        Event::AgentPromptSteered(prompt) if prompt.text == ":skill missing-steered-skill"
    )));
    h.resolving_initial_extension_collisions = false;
    h.dispatch_prompt_for_agent(
        &cid,
        PendingPrompt::user("after steered missing skill".to_owned()),
    )
    .expect("dispatch later no-ctx prompt");
    assert!(event_log_events(&h).iter().all(|event| !matches!(
        event,
        Event::AgentPromptCreated(prompt)
            if prompt.ctx_id.as_deref() == Some("prompt-steered-skill")
    )));
    assert!(read_nth_prompt_created(&h, 0).ctx_id.is_none());
}

